(window.__SYN=window.__SYN||{})[1]=[{"d":1,"t":["عيد النيروز رأس السنة القبطية","تذكار شفاء أيوب الصديق","استشهاد القديس برثولماوس الرسول","نياحة البابا ميليوس البطريرك الثالث من بطاركة الكرازة المرقسية","نياحة البابا مرقس الخامس البطريرك الثامن والتسعين من بطاركة الكرازة المرقسية"],"b":"وؤ ضوهن - في هذا اليوم تعيد الكنيسة برأس السنة القبطية» وثقام الاحتفالات الكئيسة والمؤمنين بفاعلية صلواتهم وطلباتهم. وقد بدأ تقويم الشهداء في بداية حكم الإمبراطور دقلديانوس سنة والكنيسة تقدم لأبنائها قصة المسيحية المبكرة في أبهى صورة؛ حينما قدم المسيحيون ذواتهم في عهد ذلك الإمبراطور ؛» كنماذج والإيمان والاحتمال ومحبة الأعداء» بل أن الكنيسة تقدم قصة الكرازة بالإنجيل للعالم أجمع وللخليقة كلها.\nوهي بذلك تعلم أن الإيمان اللسيحي في طوره المبكر انتشر بسفك دماء الشهداء والقدوة أكثر من انتشاره بالوعظ والتعليم.\nهذا اليوم مقدسا بكل طهر ونقاوة؛ ولنبتعد عن الأعمال المرذولة» ونبتدئ بأعمال جديدة مقدسة كقول القديس بولس الرسول ( إن كان أحد في المسيح فهو خليقة جديدة» الأشياء قد مضت» هوذا الكل قد صار جديدا ) \"\". وقال داود الني ( بارك رأس السنة بصلاحك فتمتلىء بقاعك دما .\nتطلب من الله أن يجدد حياتنا ويحفظنا بغير خطية بشفاعة القديسة العذراء مريم وطلبات جميع الشهداء الأطهار آمين.\n7 رثبت الكنيسة أن يكون هذا اليوم تذكارا لشفاء أيوب البار. وكان يسكن في أرض عوص نسبة إلى جده عوص. ويشهد الكتاب المقدس عن هذا الصديق أنه كان كاملا ومستقيما يتقى الله ويد عن الشر ”\". كما شهد الكتاب عنه أنه كان غنيا جدا في الأموال ( كان هذا الرجل أعظم بنى المشرق ) \". تنبأ أيوب عن .\nمجيء السيد المسيح لفداء البشرية بقوله ( أما أنا فقد علمت أن ولبي حي ويظهر على الأرض في آخر الزمان ) ”. كما كان يؤمن بخلرد النفس والحياة بعد اللوت رغم أنه عاش قبل الناموس بزمن طويل فيقول ( وبعد أن ينى جلدي هذا وبدون جسدي أرى الله ) \".\nكر م لا مز 19: اا.\n1 يو ب : ؟.\n'\" أيوب 19: .7 أيوب ق أياء سعيه بفضائل كثيرة مثل الطهارة كقوله:\n( عهدا قطعت لعيني فكيف أتطلع في عذراء ) © » والشفقة على الفقراء والمساكين ( فتحت للمسافر أبوابي » هل أكلت لقمتىي ولم يأكل منها اليتيم» منذ صباه كبر عندي كأب ) \".\nبعبادة الله رغم انتشار عبادة الأصنام حوله ( إن كنت قد نظرت إلى النور حين أضاء أو إلى القمر يسير بالبهاء وغوى قلي سرا. لأني أكون قد جحدت الله من فوق 4 1 با والاتكال :\nعلى الله لا على الغنى ( إن كنت قد جعلت الذهب عمدت أو قلت أنت متكلي» إن كنت قد فرحت إذ كثرت ثروت ) © بحياة التوبة المستمرة ( إن كنت قد كتمت كالناس ذني في حضني بل كنت أخبره بعدد خطواتي ) ©.\nسمح الله بالتجارب لأيوب لأنه يعرف أصالة معدنه وقوة إمانه بالله ولكي يقي منه معلما اللصير والاحتمال إلى اخر الدهور ”\". ولما أدت التجربة مهمتها مهمتها رفع عنه الله هذه التجربة وعاد أيوب إلى مجده الأول مضاعفا.\nالرب نعمة الاحتمال ببركة صلوات هذا الصديق العط أمين.\n. :7 أيوب !© أيوب 4:71 1.\n'\"؟ يعقوب .4:\nوفيه أيضا من سنة الام استشهد القديس برثولماوس الرسول أحد الاثنى عشر تلميذا. كان هذا الرسول من إقليم الجليل؛ وهو عينه نثنائيل الذي ذكر عنه القديس يوحنا الإنجيلي أن القديس فيلبس الرسول أحضره للسيد المسيح \". وقد لازم الرب يسوع فترة خدمته على الأرض » وكان له شرف رؤية الرب بعد القيامة على بحر طبرية مع بعض التلاميذ \"؛ كما حضر حلول الروح القدس يوم الخمسين. | \"© بش هذا الرسول ق بلاد اليمن؛ ؛» وترك لهم نسخة من إنجيل متى باللغة الأرامية حيث كانت توجد جالية يهودية كبيره هناك.\nكما أنه بش في بلاد أرمينيا» ومازالت تعتبره الكنيسة الأرمنية حيث أنه استشهد بهاء بركة صلواته فلتكن معنا آمين.\nوفيه أيضا من سنة تليح القديس ميليوس البطريرك الثالث من بطاركة الكرازة امرقسية؛ كان جلوسه على الكرسي المرقسي في سنة /م خلفا للقديس إنيانوس. وقد أحسن هذا القديس في رعايته بكل عفة وطهارة وأمانة وتواضع. وقد شمل الهدوء الكنيسة في أيامه؛ بما أدى إلى زيادة عدد المسيحيين في مصر والخمس مدن الغربية. وأقام على الكرسي ي أثنتي عشر سنة.\nبركة صلواته فلتكن معنا مين 8 - وفيه آ يضا من سنة 771 للشهد أء ) 49 احا م 4 تنيح لا با :مرقس الخامس البطريرك الثامن والتسعون من بطاركة الكرازة المرقسية.\nكان هذا الأب من أهالي البياضية \". مال منذ شبابه إلى حياة والعبادة فترك العالم وذهب إلى دير القديس مكاريوس ببرية شيهيت» حيث ترب هناك. وبعد انتقال البابا غبريال الثامن؛ وقع اختيار الأساقفة والأراخنة على الراهب مرقس المقاري ليكون بطريركا. وتمت رسامته يوم لأحد 71 من بؤولة سلة للشهداء ( )»؛ في كنيسة الشهيد مرقوريوس أبى سيفين بمصر القديمة» باسم مرقس الخامس.\nوكان هذا البابا الجليل عالما مثقفا في كل العلوم والشرائع الكنسية. وقد نالت هذا البابا تجارب شديدة من بعض أبنائه بسبب الأحوال الشخصية. ولكنه ظل صامدا متمسكا بتعاليم الإنجيل المقدس حتى أهلك الله هؤلاء المقاومين.\nوقد قام هذا 0 الجليل بزيارات تفقدية لأبنائه ق الصعيد.\nوكان مقره البطريركي في كنيسة القديسة العذراء الأثرية بحارة زويلة.\nولما أكمل سعيه الصالح تنيح بسلام. فصلوا عليه في كنيسة البطريركية ونقلوه إلى دير القديس مكاريوس ببرية شيهيت حيث ذفن هناك بإكرام جزيل.\nبركة صلواته فلتكن معنا ولربنا المجد دائما أبديا آمين.\nقرية بم ركز ملوى محافظة المنيا.\nيلف"},{"d":2,"t":["استشهاد القديس يوحنا المعمدان","استشهاد القديس داسيه الجندي"],"b":"المعمدان بن زكريا الكاهن على يد هيرودس أنتيباس. وذلك لأن يوحنا وبخه من أجل هيروديا زوجة أخيه فيلبس عندما زوجة له وكان زوجها حيا. ( فحنقت هيروديا عليه وأرادت أن تقتله ولم تقدر. لأن هيرودس كان يهاب يوحنا عالا أنه رجل بار وقديس وكان يحفظه : وإذ #بمحه فعل كثيرا و\"سممعه وإذ كان يوم موافق 8 صنع هيرودس في مولده عشاء الجليل دخلت ابنة هيروديا معه. فقال الملك للصبية مهما أردت أطلبي منى فأعطيك. . وأقسم لها أن مهما طلبت منى حتى نصف مملكتى. فغرجت وقالت لأمها ماذا فقالت رأس يوحنا المعمدان. فدخلت للوقت بسرعة إل الملك وطلبت قائلة: أريد أن تعطيني حالا رأس يوحنا المعمدان على طبق. فحزن الملك جدا. ولأجل الأقسام والمتكئين 1 يرد أن يردها فللوقت أرسل الملك سيافا وأمر أن يؤتى برأسه.\nفمضى وقطع رأسه ق السجن و تى برأسه على طبق وأعطاه أعطته لأمها . ولما ممع تلاميذه جاءوا ورفعوا يلف جسده ووضعوه في قب ) !\". أما الرأس المقدس فطار في الجو.\nوهو يصرخ قائلا \" لا يجل لك أن تأخذ امرأة أخيك \".\nبركة شفاعته فلتكن معنا أمين.\n> وفيه أيضا استشهد القديس داسيه الجندي وهو من أجناد إريانوس والى أنصنا. وكان من أهل تندا التابعة لمركز ملوي محافظة المنيا. هذا القديس لما رأي عظمة المسيحيين وقوة لعذابات الاستشهاد أعلن إعانه بالسيد المسيح. ولما 1 يفلح الوالي في إرجاعه» أمر بقطع رأسه. فنال إكليل الشهادة.\nبركة صلواته فلتكن معناء ولربنا المجد دائما أبديا آمين.\nيتف"},{"d":3,"t":["اجتماع مجمع بمدينة الإسكندرية في عهد البابا ديونيسيوس بشأن خلود النفس","نياحة القديسة يئودورة التائبة"],"b":"- في مثل هذا اليوم من سنة 49 م اجتمع مجمع مقدس بمدينة الإسكندرية ف السنة الثانية من رياسة البابا ديونيسيوس البطريرك الرابع عشر من بطاركة الكرازة المرقسية بسبب قوم في بلاد العرب يعتقدون بوت الروح مع الحسد معا في يوم القيامة. وقد كتبوا هذا المعتقد في رسالة إلى بعض المسيحيين بالإسكندرية. . وعلم بذلك\" واهتم بالأمرء فجمع هذا لمجمع وناقشهم وبين ضلالهم. ولمار رأي تمسكهم بآرائهم الفاسدة حرمهم.\nووضع مقالا جاء فيه: :إن الروح لا تموت ولا تضمحل بل هي باقية كبقاء الملائكة» وأنها روحانية لا تقبل تغيرا ولا وحينما تخرج من الجسد تؤخذ إلى موضع حسب إما الفردوس أو الجحيم. وأنها تتحد يجسدها في يوم القيامة العامة عندما ينفخ رئيس الملايكه في البوق فتقوم الأجساد بأمر مكونها. ذهب إما إل ملكوت السماوات 7 جهنم النار الأبدية. وتبقى مع جسدها في المكان الذي وصلت إليه إلى أبد الآبدين ).\nبركة صلوات هذا البابا الجليل فلتكن معنا آمين.\nوفيه أيضا من سنة 177 للشهداء ( ) تشحت القديسة ثمئودورة التائية.\nفي القرن الخامس الميلادي في عهد الإمبراطور زينون؛ من أبوين شريفين بالإسكندرية » اتسمت بالجمال البارع مع الحياة التقوية والغنى. . تزوجت شابا غنيا وتقيا. وكانت حياتهما مملوءة سلاما وفرحا. في وسط مظاهر الغنى تعرف عليها شاب غنى أعجب بحكمتها واتزانها وكان تقيا وطاهرا فصارت بينهما ولكن عدو الخير بدأ بعل فتثرة يلقى فيه بذار الفكر الشرير من جهة ثيئودورة» وتزايدت الحرب حتى وجد الشاب فرصة من جهتها. فصدمت إذ كانت ترى فيه النقاوة » وانتهرته. مرت الأيام وتزايدت الأفكار حتى سقطا في الخطية. ل يعرف أحد مااحدث» خاصة والكل يعلم أنهما لكن ثيشودورة لم تختمل نفسهاء وفي صراعهاء ما حدث والدموع تنهمر من عينيها. وم يعرف ماذا يعمل الأنه كان يثق في زوجته وصديقه» وتحولت إلى دموع لا تنقطع» وأخيرا قررت أن تترك العا بقية أيامها في توبة. فحلقت شعر رأسها وتزيت بزى الرجال وانطلقت ليلا إلى دير الأناطون بالدخيلة بالإسكندرية وهناك سألت رئيس الدير أن يقبلهاء فأراد أن يختبرها فتركها على الباب طول الليل وسط البرد الشديد. وفي الصباح وجد أن عينيها قد تؤرمتا بسبب البكاء»: فسمح لها بالدخول وعرفت الراهب تاؤدور أو تادرس.\nالقديسة في هذا الدير تمارس خدمة فلاحة البساتين كل تعب بفرح وسرور. وصلواتها لا تنقطع وسط أتعاب مع النسك الشديد.\nوقد وهبها الله عطية صنع المعجزات» فذاع صيتهاء ووفد على الدير كثيرون يطلبون بركتها. وكان زوجها يئن بلا لا يعلم مكانها وكان مشتاقا أن يطمئن على خلاصها.\nبدموع صلوات. وفي عمره حزنه» ظهر له ملاك يسأله أن يذهب إلى كنيسة القديس بطرس خاتم الشهداء ليجدها بجوار الكنيسة بمفردها. ولما انطلق لم يجد هناك سوى راهبا يقود جالا.\nوكان هو نفسه ثيشودورة التي لم يعرفها زوجها لتغير شكلها بسبب شدة نسكها. أما هي فعرفته وحيته فرد عليها التحية.\nولما رأي عدو الخير أنها أفلتت من مخالبه . حرك امرأة شريرة إلى رئيس الدير تشكو أن هذا الراهب أفسد عفتها.\nوقد احتملت القديسة السخرية بتسليم كامل دون أن تدافع عن نفسها حتى لا يعرف أحد سرها. وطردت من الدير مع الرضيع لمدة سبع سنوات في البريةء فذاقت فيها كل تعب وألم خاصة من أجل الطفل البريء. وكانت تجاهد حاسبة أن ما جرى لا من قبيل التأديب وإذ أظهرت كل ثبات مع التوبة » سمح لها رئيس الدير بالعودة مع الطفل» بعد أن وضع عليها تأدييات وطلب منها أن تبقى في قلايتها مع ابنها ولا تقابل أحدا خارج الكنئيسة؛ وعند قرب نياحتها أوصت الابن المنسوب إليها قائلة له: (يا ولدى لقد قاربت شمسي أن تغيب لكنى أتركك بين يدي أب عطوف هو الله أب اليتامى - جميعا. وأملى أن رئيس الدير لا يتخلى عنك والرهبان يعطفون عليك. يا ولدى لا تبحث عن أصلك ونسبك. إن خير الأنساب هو ما يأتينا من الفضيلة. لا تنظر إلى الأمجاد العالمية. ولقد قال الرب يلسوع لكم إذا طردوكم وعيروكم وقالوا عليكم كل كلمة شريرة من أجلى كاذبين. صل لأجل الخطاة. كن عونا للضعيف. اخدم كما لو كان سيدك» لكي تكون مقبولا عند المسيح يسوع الذي لأجلنا أخذ صورة عبد )» وبتدبير الله كان رئيس الدير خارج القلاية يستمع إلى هذه النصائح فتأكد أن هذا الراهب مفترى عليه. فطرق الباب ليدخل وينال بركته قبل ولما دخل وجده قد فاضت روحه..\nالرهبان إلى جثمان الراهب تاؤدور ليعلنوا أسفهم وإذ أرادوا دفنه أدركوا أنها امرأة؛ فزاد تعجبهم. وللحال انتشر الخبر في كل الإسكندرية. وجاء كثيرون يطلبون بركتها. عندكذ أدرك زوجها أنها امرأته» فتوسل لدى رئيس الدير أن يقبله راهبا بقية أيامه ف ذات قلايتها. أما الصي فكان ينمو في النعمة حتى أحبه الجميع.\nبركة صلواتها فلتكن معنا. ولربنا المجد دائما أبديا آمين."},{"d":4,"t":["نياحة البابا مكاريوس الثاني البطريرك التاسع والستون من بطاركة الكرازة المرقسية","نياحة القديسة فيرينا"],"b":"-1 تذكار يشوع بن نون.\nووو 0 1- ق مثل هذا ا ليوم من سنة 7016 للعا ل تنيح أ لني إ لعظيم يشوع بن نون. ولد ق مصر سنة 757050 للعالم وهو من سبط أفرا يم.\nخرج مع موسى مع شعب بنى إسرائيل من مصرء وأصبح تلميذا لموسى الني.\nوفي أثناء حرب بنى إسرائيل م عماليق كان هو يقود الجيش بينما موسى على الجبل يصلى \" فهزم يشوع عماليق وقومه بحد السيف )0 » ولما انتخب موسى 1 ني عشر رجلا ليكتشفوا أرض المميعاد. كان يشوع واحدا منهم وقد أتم خدمته بكل أمانة هو وكالب الأخبار الصادقة لموسى عن هذه الأرض.\nلذلك دخل هذان الاثنان فقط تلك الأرض دون جميع الشعب الذي خرج من مصر بسبب تذمرهم وشكوكهم في صدق وكان بعد موت موسى الني أن الرب كلم يشوع بن نون خادم موسى قائلا: ' ' موسى عبدي قد مات فالآن قم اعبر هذا الأردن أنت وكل هذا الشعب إلى الأرض التي أنا معطيها لطهم.\nخر 19 لحكلا لقف كل موضع تدوسه بطون أقدامكم لكم أعطيه كما كلمت موسى. كما كنت مع موسى أكون معك لا أهملك ولا أتركك لأنك أنت تقسم لهذا الشعب الأرض التي أن أعطيهم. كن متشددا وتشجع جدا لكي للعمل حسب كل الشريعة التي أمرك بها موسى عبدي\" ولا شالا لكي تفلح حيثما تذهب. لا يبرح سفر هذه الشريعة من فمك بل تلهج فيه نهارا ولبلا لكي تتحفظ للعمل حسب كل ماهو مكتوب فيه لأنك حينقذ تصلح أما أمرتك. تشدد وتشجع. لا ترهب ولا لأن الرب إلهك معك حيثما تذهب \" \".\nفتقوى قلب يشوع فأرسل جاسوسين إلى الأرض ولما اطمأن قا وعبر الأردن بعد أن انشق نشق أمامهم 0 كما انشق البحر الأحمر أمام موسى. وفتح أريحا بعد أن طاف حولها سبعة ة أيام فسقطت أسوارها. وكان الرب مع يشوع فقتل ملوكا وقح مدنا كثيرة وقسم الأرض لبنى إسرائيل حسب أسباطهم.\nولما أكمل سعيه الصاح ووصل إلى شيخوخة حسنة استدعى شيوخ بنى إسرائيل ورؤساءهم وأوصاهم أن لا يجيدوا عن عبادة الله وان يتمسكوا بناموسه تنيح بسلام وعمره مئة وعشرة سنين بركة صلواته فلتكن معنا. آمين.\n7 - في مثل هذا اليوم من سنة 8406 للشهداء تنيح اليبانا القديس الأنبا مكاريوس الثاني البطريرك التاسع والستون من بطاركة الكرازة المرقسية.\nكان هذا الأب عابدا منذ صغره. ترهب بدير القديس مكاريوس متفرغا للعمادة والنسك وقراءة الكتب المقدسة.\nفي الفضيلة» وكان فنانا بارعا » يقضى بعض أوقاته ق رسم الأيقونات وتزيين المخطوطات.\nولما خملا الكرسي المرقسي بنياحة البابا ميخائيل الرابع البطريرك الثامن والستين. قرر المجمع الملقدس الذي انعقد بالقاهرة انتخاب الراهب مكاريوس. فأخذوه وقيدوه وهو يصيح ويحتج بأنه لايصلح لهذه المسئولية الخطيرة. ولكنهم ذهبوا به إل الإسكندرية وثمت رسامته بكنيسة القديس مار مرقس يوم الأحد من هاتور سنة 8149 للشهداء (م).\nثم توجه إلى مقر كرسيه بالقاهرة حيث أقيم له طقس تجليس بكنيسة القديسة العذراء المعلقة.\nوكان هذا الأب مدة رئاسته يتزايد في النسك والعبادة» مداوما على تعليم الشعب ووعظه وكان كثر الصدقات والرحمة على الفقراء والمساكين. ولما أكمل سعيه تنح بسلام وصلى عليه الآباء الأساقفة ودفنوه بإكرام بكنيسة القديسة العذراء المعلقة. وكانت مدة رئاسته خمسا وعشرين سنة وتسعة أشهر.\nبركة صلواته فلتكن معنا أمين.\n7- وفيه أيضا من سنة 44 ام تشحت القديسة الكارزة عروس المسيح الطاهرة معلمة النظافة القديسة فيرينا. ولدت هذه القديسة في أسرة قبطية في قرية جاراجوس بإقليم طيبة بالصعيد العلى واسم يرينا يعني ( ثرة طيبة ). نالت المعمودية على يدي أسقف قديس يدعى شيرامون أسقف مدينة نيلوس وهو الذى أشرف على تعليمها ونشأتها الدينية فتعلمت الصلاة ونمت في النعمة والقامة حتى صارت شابة هادكة وكانت والدتها تباشر صناعة ملابس خدمة الكهنوت. وكان عدد كبير من المسيحيين في ذلك الوقت يجاهرون بإيمانهم ضد الرومان وينالون إكليل الشهادة. وكانت فيرينا أيضا تشتاق إلى أن تنال نصيبها من الاضطهاد والاستشهاد وكانت تزور المحبوسين من المسيحيين وتقدم لهم ما يحتاجونه.\nوفي عهد الإمبراطور دقلديانوس 184 - 05 ذاع صيت الكتيبة الطيبية التي كان على رأسها القائد موريس الشجاع التقي الذي كان من مديئة طيبة. أصدر الإمبراطور أوامره فرقة القديس موريس إلى غرب أوربا لمساعدة الإمبراطور مكسيميانوس ولإخماد ثورة شعب الباجور يجنوب شرق فرنسا. وقد رافقت القديسة فيرينا والقديسة ريجولا والقديس فيكتور والقديس فيلكس هذه الحملة إل غرب أوربا.\nجميع فصائل الكتيية وكان عددهم ستة آلاف وعلى رأسهم القائد موريس ومعه كبار الضباط رتلف مات له وخلف الجميع وقفت القديسة فيرينا انتظارا لتحرك الكتيبة لإخماد ثورة شعب الباجور. ض وطلب الإمبراطور مكسيميانوس من الكتيبة تقديم البخور للآلهة الوثنية فرفض الجميع فأمر بقطع رؤوسهم جيعا ونالوا إكليل الشهادة وعلى رأسهم القديس موريس. وأما القديسة فيرينا فبدأت سيرها نحو الشمال وعبرت جبال الألب في في كهف ضيق في شمال سويسرا مع مجموعة من العذارى وكانت فيرينا تجيد حياكة الملابس وتطريزها.\nوبدأت القديسة تتعلم لغتهم حتى أجادتها وقدمت معرفتها الأمراض عن طريق الأعشاب الطبيعية؛ وكانت القديسة كالمنارة تضيء لمن حولمها واعتبروها أما لجميع القديسة حياتها لله في خدمة الفقراء الذين أن تقدم لهم الطعام والعناية بالمرضى والعناية بالنظافة والاهتمام بالمظهر العام. واستمرت في جهادها وصلاتها رغم وضعف جسدها وكانت حياتها مزيجا من الخدمة مع . الاعتكاف للعبادة والتأمل.\nوعندما حان وقت رحيلها عن العالم ظهرت لا القديسة العذراء مريم ومعها بعض العذارى في قلايتها وبشرتها ببركات الحياة الأبدية ونعيم الفردوس. فقامت القديسة فيرينا من وقالت كيف أستحق أن تأتي أم ربي ولحي إلى خادمتها؟\nفقالت لها والدة الإله لكي أكافئك على أمانتك التي خدمتي بها مع هؤلاء وافرحي معهم إلى الأبد. وامتلات القلاية من رائحة البخور وانتقلت إلى السماء وتعيد لها الكنيسة في جثل هذا اليوم.\nوقد استلم قداسة البابا شنوده الثالث البطريرك !! المائة والسابع عشر من بطاركة الكرازة المرقسية جزء من رفات القديسة فيرينا الموجود بكنيستها بتسورتساخ بسويسرا.\nبركة صلواتها فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":5,"t":["استشهاد القديسة صوفيا"],"b":"في مثل هذا اليوم من القرن الثاني المسيحي» استشهدت القديسة صوفيا. وللدت هذه القديسة في منف \" بمصر من أبويين وثنيين؛ ولكنها عرفت السيد المسيح واعتمدت على يد أسقف منف؛' البيعة. وكان ذلك في أياء البابا أومانيوس البطريرك السابع | من بطاركة الكرازة المرقفسية» وفي عهد الإمبراطور هدريان» حيث .\nأعلن الاضطهاد بشدة على المسيحيين الأقباط. فلما رأت جازاتها ذلك؛ أبلغن الوالي كلوديوس بأمر هذه القديسة.\nوسألها عن إيمانها. فأقرت أنها مسيحية وم تنكر. .\nبأعصاب البقر وكوى مفاصلها. ولكنها ثبتت على الإيمانء وكانت تصيح أنا مسيحية» فاغتاظ الوالي وأمر بقطع لسانها.ولما تعب من تعذيبها» ألقاها في السجن. ثم أرسل إليها زوجته لكي تلاطفها بترك إيمانها. ولكنها ثبتت على الإيمان.\nولما رأي الوالي إصرارها أمر بقطع رأسها. فصلت وأحنت رأسها فقطع رأسهاء ونالت إكليل الشهادة. فأخذت امرأة منف: مدينة مصرية قدركة ورد ذكرها في الكتاب القدس باسم نوف ( إش 19: ) وسميت ق العصر اليوناي والروماي نمفيس - وتسمى الآن ميت رهيئة _ مركز البدرشين وهي إحدى المدن الأثرية القديمة بممحافظة الجيزة.\nيفف مسيحية جسدها الطاهرء ولفته بلفائف ثمينئة ووضعته في بيتهاء؛ فكانت تظهر منه آيات كثيرة.\n: وف يوم عيدهاء كانوا ينظرون نورأ عظيما يشع من جسدها.\nمنه رائحة طيبة. ولما تملك الملك قسطنطين الكبير وسمع أرسل فنقل جسدها الطاهر إل مدينة القسطنطينية حيث بنى كليسة سلميت باسم (أآجيا صوفيا ). وكانت آية في الجمال.\nحتى جعلها تحفة الشرق. وفي الوقت الحاضر تحولت هذه الكنيسة إلى متحف بسبب روعة معمارها وزخارفها الكثيرة ولا زالت تحمل نفس اسم القديسة صوفيا."},{"d":6,"t":["استشهاد إشعياء النبى بن آموص","استشهاد القديسة باشيلية أو باسيليا"],"b":"- في مثل هذا اليوم من حوالي سنة قبل الميلاد استشهد الني العظيم إشعياء بن أموص أحد الأنياء الكبار. ومعنى اسبممه ( الرب يخلص »» وهو من سلالة ملوك يهوذا. وقد تنأ هذا الني أيام عزيا ويوثام وأحاز وحزقيا ومنسى ملوك يهوذا. كما أنه عاصر من الأنبياء عاموس وهوشع وعوبديا وميخا وناحوم.\nفي سنة وفاة عزيا الملك سنة 148 ق.م» رأي إشعياء في الهيكل ' ومع دعوة الله له ليقوم بالعمل النبوي ”\". دعا إشعياء امرأته بالنبية 0 . وأعطى ولديه أ “مين رمزيين. . أحدهما ( شآر يشوب ) \" أي ( البقية ترجع ). والثاني ( مهير شلال 0 أي ) يجل السلب ويسرع النهب 6 وف سنة 1 . م أعطى وعدا لأآحاز الملك بأن الله سوف ينقذ يهوذا من إسرائيل وآرام 6 ولم يقبل أحاز كلام إشعياء. . أما حزقيا الملك فقد ولما مرض احزقيا تنأ إشعياء بشفائه .2 بركة صلواتها فلتكن معنا.\nولربنا المجد دائما أبديا آمين\n0 إشش ولما حاصر ستحاريب ”\" ملك أشور أورشليم» تنبا إشعياء أثناء الحصار» بأن الرب لابد أن ينقذ المدينة. وفعلا أرسل الرب ملاكه وقتل من جيش ستحاريب 89 ألف جندي. واضطر سنحاريب إلى الانسحاب والرجوع إلى بلاده.\nنبوة إشعياء الفترة من سنة ق. م. إلى سنة هذا وقد ورد ج سفره كثير من النبوات عن ميلاد السيد المسيح المعجزي: : ( يعطيكم السيد نفسه آية. هوذا العذراء وتلد ابنا وتدعو اسمه عمانوئيل ) ”\". ( يولد لنا ولد ابنا وتكون الرياسة على كتفه ويدعى اسمه عجيبا مشيرا إلها قديرا أبا أبديا رئيس السلام ) . كما تنبا عن مجيء السيد المسيح وأمه العذراء مريم إلى مصر بقوله: ( هوذا الرب راكب على سحابة سريعة وقادم إلى مصر فترتجف أوثان مصر من وجهه ويذوب قلب مصر داخلها ) \".كما تنبا عن تأسيس الكنيسة في مصر بقوله: ( في ذلك اليوم يكون مذبح للرب في وسط أرض مصر وعمود للرب عند تخمها فيكون علامة لرب الجنود في أرض مصر ) . وأيضا تنبأ عن آلام السيد المسيح الخلاصية واحتماله بصبر بقوله: ( ولكن أحزاننا إش ا اي )0 إش :67 - لا ونحن حسبناه مصابا مضروبا من الله وهو مجروح لجل معاصينا» مسحوق لأجل آثامنا.\nعليه وبحبره شفينا. كلنا كغنم ضللناء ملنا كل واحد إلى طريقه؛ والرب وضع عليه إثم جميعنا. ظلم أما هو ولم يفتح فاه. كشاة تساق إلى الذبح وكنعجة صامتة أمام.\n» فلم يفتح فاه ) . | من أجل هذا دعاه الآباء ( الي الإنجيلي بسبب كثرة نبواته عن السيد المسيح. وقد عاش هذا الي حتى زمن منسى الملك الشرير. حيث يذكر التقليد أنه نشره بمنشار لكثرة توبيخه له على وهكذا أكمل هذا الي العظيم جهاده ونال إكليل الشهادة.\nبركة صلواته فلتكن معنا أمين.\n- وفييه أيضا استشهدت القديسة باشيلية أو باسيليا ف أيام دقلديانوس الكافر. وقد كانت هذه القديسة مسيحية. ألقى القبض عليها وهي في التاسعة من عمرها. وثبتت على شهادتها يديها ورجليهاء وألقوها في النار» ولكن الله وإذ عطشت أنبع الله الماء بصلاتها. ثم أودعت حياتها .\nفي يد الرب ونالت إكليل الشهادة.\nبركة صلواتها فلتكن معناء ولربنا المجد دائما أبديا آمين.."},{"d":7,"t":["نياحة البابا ديوسقوروس البطريرك الخامس والعشرين من بطاركة الكرازة المرقسية","نياحة البابا يوأنس الثاني عشر البطريرك الثالث والتسعين من بطاركة الكرازة المرقسية","استشهاد القديسة رفقة وأولادها الخمسة أغاثون وبطرس ويوحنا وآمون وآمونة","نياحة القديس سوريانوس أسقف جللة"],"b":"ومو يجيو ميجو - في مثل هذا اليوم من سنة 1771 للشهداء ( ) تنح الأب المغبوط البابا ديوسقوروس البطريرك الخامس والعشرون من بطاركة الكرازة المرقسية. | ولد بالإسكندرية وتعلم بمدرستها اللاهوتية وأظهر نبوغا عظيما في دراستها فأعجب به القديس كيرلس الأول البطريرك الرابع والعشرون» وعينه سكرترا خاصا له وهذا الملنصب العظيم لم يشغل القديس عن الدرس والإطلاع بل كان يبحث في مؤلفات الآباء.\nجلس هذا الأب على الكرسي المرقسى يوم ؟ مسرى سنة للشهداء ”© خلفا للبابا كيرلس الأول عمود الدين.\nوقد ساد السلام في الكئيسة في الخمس سنوات الأولى من في عهد الملك الأرثوذكسي بئودوسيوس الصغير..\n)0 تقابل 47 بالتقويم الغربي. ( حيث أن السنة الميلادية الغربية تنقص روما عن السنة ' ' الميلادية الشرقية ).\nرأس البابا ديوسقوروس مجمع أفسس الثاني في أغسطس سنة وبعد أن سمع المجمع اعتراف أوطاخي كتابة أثناسيوس وكيرلس المستقيم ورفضه ما من أن الناسوت امتص في اللاهوت. وبعد أن أعلن توبته وإمانه بأن في المسيح يسوع طبيعة واحدة من طبيعتين. أقر المجمع قبول توبته وإعادته إلى درجته وديره. كما حكم المجمع فلابيانوس أسقف القسطنطينية وستة أساقفة معه بسبب التي تقول بوجود طبيعتين للسيد المسيح بعد الإتحاد. اتحد فلابيانوس مع لاون أسقف روما ضد ديوسقوروس. عقد القديس ديوسقوروس مجمعا بالإسكندرية حرم فيه لاون أسقف روما لأنه تمسك بأفكار فلإبيانوس مات الإمبراطور يئودوسيوس سنة غربية واعتلى الكرسي مركيان الذي تزوج بولشاريا أخت ثيئودوسيوس وكان يميل إلى أفكار نسطور» كما كانت بولشاريا والدهاء وكانت تخشى قوة ديوسقوروس وتعمل على إضعاف مركزه.\nانتهز لاون فرصة اعتلاء مركيان لكرسي القسطنطينية وبعث إليه برسالة يشكو فيها ديوسقوروس الذي حرمه؛ ويطلب فيها عقد مجمع لمناقشة الإيمان من جديد.\nرد عليه مركيان بإيعاز من زوجته بولشاريا بأنه مستعد لعقد فعقد اجتماع تمهيدي بقصر الإمبراطور بالقسطنطينية حضره البابا ديوسقوروس. حاولوا الضغط على ديوسقوروس لكي يوافق على رسالة لاون التى تثبت الطبيعتين بعد الإتحاد.\nفقال ديوسقوروس في جرأة أن اعتقاد الآباء ينبغى ألا يزاد عليه أو ينقص منه وأن المسيح كما علمنا الآباء واحد بالطبع والفعل وإن إتحاد اللاهوت بالناسوت هو كاتحاد النار وكانت النتيجة أن تهجمت الملكة بولشاريا الشريرة شديدة ثم امال عليه بعض رجال\" القصر وأوسعوه ضربا حتى اقتلعوا ضرسين من أضراسه؛ شعر لحبته. أما هو فبقى صامتا وهو يقول من أجلك يارب ثمات كل النهار. ثم جمع الضرسين مع الشعر وأرسلهم إلى شعبه بالإسكندرية مع رسالة يقول فيها ( هذه نتيجة جهادي من أجل الإيمان ).\nبعد هذا عقد مجمع بأمر الملك مركيان في مدينة خلقدونية القريبة من القسطنطينية سنة غربية واستخدموا فيه ضد ديوسقوروس والأساقفة الأقباط. وقد ثبت في الجلسة الأول منه سلامة موقف ديوسقوروس. فرفعت الجلسة على أن يعود المجمع للانعقاد بعد خمسة أيام . ولكن بعد أياء تم عقد جلسة حضرها نواب أسقف روما وبعض له. ومنعوا ديوسقوروس من حضورها بأن ريف وضعوا حراسا على مقر إقامته ولم يحضرها أيضا نواب الملك وفيها أقروا يمان لاون بالطبيعتين والمشيئتين للسيد المسيح ديوسقوروس غيابيا. طلب ديوسقوروس قرار المجمع؛ وبعد أن قرأه على أساقفته وإذ وجده مخالفا للإيمان السليم كتب عليه بخط يده حرما لهذا المعتقد وكل من يعتقد به ثم أرسله ولما رأوا الحرم مكتوبا عليه غضبوا وأرسلوه إلى الملك مركيان الذي غضب وأراد قتل ديوسقوروس» ولكنه إذ أدرك بركة صلواته فلتكن معنا آمين.\nوفيه أيضا من سنة 8 للشهداء ( )» تنيح البابا يوأنس الثاني عشر البطريرك الثالث والتسعون من بطاركة الكرازة المرقسية. ولد هذا الأب في بلدة نقادة \"» فرباه أبواه تربية مسيحية حقيقية ولما كبر اشتاق إلى السيرة الرهبانية فذهب إلى دير العذراء المعروف بالمحرق 6 وترهب فيه ونما ج الفضيلة والزهد فر “موه فقسا وعند خلو الكرسي البطريركي بنياحة البابا ميخائيل الرابع. وقع اختيار الأساقفة والشعب على هذا الآب» فرسموه بطريركا باسم البابا يوأنس الثاني عشر يوم ذكر ق بعض المراجع أكنا تسمى عنغرا وتقع على ساحل أ سيا الصغرى .\n00 نقادة مركز تابع لمحافظة قناء وبه أديرة قليعة كثيرة.\nايف برمودة سنة 43 للشهداء ( ). فلما جلس على الكرسي المرقسي رعى الشعب المسيحي أحسن رعاية وأقام على الكرسي ثلاث سنوات وأربعة أشهر معلما ومفسرا الكتب المقدسة باستقامة. ولما أكمل سعيه الصاح تنيح بسلام ودفن بكنيسة العذراء بابلون الدرج بمصر القديمة.\nبركة صلاته فلتكن معنا أمين.\n- وفيه أيضا استشهدت القديسة رفقة وأولادها الخمسة أغاثون وبطرس ويوحنا وأمون والطفلة آمونة ق عهد دقلديانوس سنة ( ).\nكانت هذه الأسرة من بلدة قامولا ''\" مركز قوص. ولما أن دقلديانوس أمر باضطهاد المسيحيين وأغلق أبواب الكنائس أقاموا الليل كله يصلون طالبين من السيد المسيح أن شعبه ويرفع عنهم الشر. وبينما هم يصلون ظهر لهم ملاك الرب يعلن لهم أنهم سينالون إكليل الشهادة على اسم السيد المسيح. ففرح القديسون بهذه الرؤياء وقاموا باكرا وفرقوا على المساكين وعتقوا عبيدهم» ثم أتوا إل مدينة قوص واعترفوا بالسيد المسيح أمام ديونيسيوس القائد. . فعذبهم عذابا شديدا. مبتدثا بأمهم التي أ ثبتت صبرا واحتمالا وكانت تقوى أولادها وتصبرهم على العذاب. ولما تعب من تعذييهم أشار عليه الذين حوله أن يرسلهم إلى الإسكندرية» لثلا يضلوا الناس ق بلادهم وذلك لأنهم كانوا محبوبين وقد أمن بسبيهم كثيرون واعترفوا بالسيد المسيح ونالوا إكليل الشهادة.\nحمل الحند القديسين إلى أرمانيوس والى إ لإسكندرية 6 وكان موجودا ببلدة يقال لما شبرا بالقرب من دمنهور. ولما عرف عذبهم عذابا شديدا بالمنبازين \" ثم ألقاهم في خلقين \" فيه زيت مغلي وفي هذا جميعه كان السيد المسيح يقويهم بلا فساد» حتى تعب الوالي وجاعته. فأمر أن تؤخذ رؤوسهم بالسيف وتثلقى أجسادهم في البحر. فقطعت رؤوسهم ونالوا إكليل الشهادة. ووضعوا أجسادهم في زورق لكي يلقوها في البحر.فأرسل الرب ملاكه لأرخن من نقرها وهي قرية بالقرب من دمنهور» وأعلمه بأمر الأجساد وأمره أن يأخذها.\nففرح الرجل وذهب إلى حيث الأجساد وأعطى الجند أموالا كثيرة وأخذ الأجساد ووضعها في الكنيسة.\nوقد أظهر الله منها آيات وعجائب كثيرة. ولما عم الخراب قرية نقرهاء قلت الأجساد إلى بلدة أخرى تسمى ديى. ولما هي الأخحرى » كان بها راهب قام بنقل الأجساد إلى مدينة سنباط. وبنيت كنيسة باسم القديسة رفقة وأولادها ومازالت الأجساد باقية حتى اليوم.\nبركة صلواتهم فلتكن معنا آمين.\nالهنبازين آلة مثل الدولاب بها أسنان حديدية تقطع جسم من يلقى بداخلها.\nقرية على البر الغربي للنيل في مقابل الأقصر وهي تتبع الآن مركز نقادة محافظة قنا. \"9 الخلقين هو المرجل أي الإناء النحاسي الكبير.\nوفيه أيضا من سنة 7 للشهداء ( ) تنح الأب القديس سوريانوس أسقف جبلة ببلاد اليونان. وكان هذا القديس قد بعلوم كثيرة. وبعد نياحة والديه أخذ أمواله وبنى بها دارا ووزع الباقي على الفقراء. ولما وصل خبره إلى الملك أونوريوس أعجب به ودعاه إليه وجعله معه في القصر.\nوما رأي القديس إكرام الناس له خشي أن يضيع تعبه» فظهر له ملاك الرب وأمره أن : بمضى إلى جبلة» وهنا سكن في دير راهب قديس. ثم جدد له الملك ثيئودوسيوس ديرا آخر أقام فيه وصار معزيا لنفوس كثيرة مداوما على تعليم الرهبان حتى صاروا قديسين كالملائكة. وقد أجرى الرب على يديه آيات كثيرة منها إخراج روح نجس من ابنة والى جبلة.\nوقد رأي أسقف جبلة رؤيا بأن القديس سوريانوس سيجلس على كرسيه من بعده؛ فأعلم بها شعبه وبعد نياحته رسبموه أسقفا عليها. فاجتهد في رعاية شعبه» حتى أمن على يديه كثيرون من اليهود والوثنيين والسحرة.\nوقد كتب مقالات وميامر ومواعظ مفيدة. ولما شاخ وبلغ عمره مائة سنة» ظهر له ملاك الرب وأعلمه بيوم انتقاله.\nشعبه وتنح بسلام.\nبركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":8,"t":["نياحة موسى النبي","استشهاد زكريا الكاهن"],"b":"استشهاد القديس ديميدس القس.\nفي مثل هذا البوم من سنة 1488 ق.م تنيح الصديق العظيم موسى رئيس الأنبياء. ولد موسى سنة # ق. 2 بمصر من أب أسبمه عمرام “ ومن أم أ سمها يوكابد 0 وكلاها من سبط لاوي في أيام الملك أمينوفيس فرعون مصرء الذي أمر بقتل كل طفل ذكر يولد للعبرانيين. وبالإبمان خبأه أبواه ثلاثة أشهر لأنهما رأيا أن الصبي جميل ولم افا أمر الملك. بعدها وضعاه فى ق من البردي مطليا بالحمر والقار» ووضعاه على حافة النيل » وكانت مريم أخته واقفة تنظر. فجاءت ابنة فرعون فرأت السفط وأرسلت إحدى جواريها فأحضرته لهاء ولما فتحته وجدت الطفل يبكي فرقت له وقالت هذا من أولاد مريم أخته وعرضت أن تحضر مرضعة ابنة فرعون» فأحضرت لا أم الطفل. فأعطته لها لكي ترضعه مقابل أجرة. فأخذته أمه وأرضعته لبنها مع لبن الإبمان الحقيقي بالله والحب لإخوته. ثم أرجعته لابنة فرعون» اسم عبري معناه ( عم مرتفع ).\nبد سم عبري معنا ه ( يهوه بحد ). خر 7: .\nا وتيف | سمه ( موسى ) أي المتشل من الماء. فعاش موسى في القصر الملكي إلى سن الأربعين وتثقف بكل حكمة المصريين؛ وصار مقتدرا في القول والعمل.\nوحدث في تلك الأيام أنه خرج إلى إخوته لينظر في أثقالهم.\nفرأى رجلا مصريا يضرب رجلا عبرانبا ؛» فقتل موسى المصري وف اليوم التالي إذا رجلان عبرانيان.\nفقال للمذنب لماذا تضرب صاحبك؟. فقال من رئيسا وقاضيا عليناء أمفتكر أنت بقتلى كما قتلت فخاف موسى وقال حقا قد غرف الأمر. قسمع فرعون هذا الأمر فطلب أن يقتل موسى. فهرب موسى من وجه فرعون وسكن في أرض مديان» حيث التقى بيثرون كاهن مديان» فزوجه صفورة ابنته ورزق منها بولدين ( جرشوم ). ,| ولما كملت له هناك أربعون سنة ظهر له الله '؟ في لهيب نار من عليقة تشتعل» فمال لينظر هذا المنظر» فناداه الله من وسط قائلا: ( أنا إله آبائك إله إبراهيم وإسحاق ويعقوب اخلع لأن الموضع الذي أنت واقف فيه أرض مقدسة. وأمره إلى مصر ليخلص بنى إسرائيل من ظلم فرعون فتزل والتقى بهمرون أخيه ودافعا معا عن الشعب الإسرائيلي أمام ولما تقسى قلب فرعون» عمل الرب على يدي موسى هذه إحدى ظهورات السيد المسيح في العهد القديم.\nالعتف ثم صنع الشعب الإسرائيلي الفصح ورشوا الدم لثلا يمسهم الملاك المهلك» فاضطر فرعون بعد قتل الأبكار أن يسمح لهم بالخروج ولما وصلوا إلى شاطىء البحر الأحمر أمر الرب موسى فضرب البحر بالعصا فانشق إلى نصفين وعبر الشعب على اليابسة» وبعدها أطبق الماء على فرعون وجنوده.\nقاد موسى الشعب في سيناء أربعين سنة وأنزل لهم الرب المن لهم الماء من الصخرة ثم سلمه الله لوحي العهد والوصايا.\nوعمل خيمة الاجتماع بحسب المثال الذي أعلمه به الله. وقد تحمل من الشعب متاعب كثيرة. وكان حليما جدا. وكان الله يكلمه كما يكلم الرجل صاحبه. ض ولما كملت له مائة وعشرون سنة أمره الله أن يسلم قيادة الشعب إلى يشوع بن نون. وبارك أسباط إسرائيل. ثم صعد إلى جبل نبو إلى قمة الفسجة تجاه أريحا حيث أراه الله أرض كنعان.\nوقال له: قد أريتك الأرض بعينيك ولكنك إلى هناك لا تعبر \".\nفمات موسى في أرض موآب ودفنه الله مقابل بيت فغور ولم يعرف إنسان قبره إلى هذا اليوم.\n! بركة صلواته المقدسة فلتكن معنا أمين.\n- وفيه أيضا استشهد زكريا الكاهن أبو القديس يوحنا المعمدان.\nوكان من فرقة أبيا. وكانت امرأته أليصابات ( وكان كلاهما بارين أمام الله سالكين في جميع وصايا الرب وأحكامه بلا لوم 6 لقف ولم يكن لهما ولد إذ كانت أليصابات عاقرا وكان كلاما في أيامهما ) © وبينما كان يرفع البخور على المذبح ظهر له جبرائيل الملا وبشره بلاد ابنه يوحنا ولما 1 يصدق كلام أ لملاك أوجب عليه الصمت حى تمت معجزة ميلاد حينئذ تكلم وسبح الله وتنبا عن يوحنا كسابق للسيد المسيح الآتي لخلاص العالم.\nولما أتى المجوس ليسجدوا للمسيح المولود؛ قلق هيرودس على ملكه وأمر بقتل ميع الأطفال ق بيت لحم وكل من ابن سنتين فما دون. ولكن ملاك الرب ظهر ليوسف حلم وأمره أن يهرب بالصى وأمه إلى أرض مصر. أما هيرودس فبعدما قتل أطفال بيت لحم» قيل له من بعض اليهود أن زكريا الكاهن قد ولد له ابن ببشارة من ملاك الرب» لعله هو الملك المقصود. فأرسل هيرودس الجند إلى زكريا يطلب الطفل فقال هم زكريا أنا أخذت هذا الصبي من مكان فهلموا من هناك. فأتوا معه إلى الهميكل » ووضعه على المذبح حيث بشره به الملاك. فخطفه ملااك الرب إلى برية الزيفانا. فلما 1 يجده الحند قتلوا زكريا أناه. وأخة خفى الرب جسده. أما دمه فصار كالحجر. وهكذا أكمل جهاده الحسن ونال الحياة الأبدية.\nبركة صلواته فلتكن معنا آمين.\nلو 1: لا.\nوفيه أيضا استشهد القديس ديميدس القس في أواخر القرن الثالث الميلادي. وكان من أهل درشابة مركز الرحمانية محافظة البحيرة. وكان محبا للكنئيسة عطوفا على المساكين مفتقدا فظهر له ملا نوراني شجعه وأعلمه أنه سيصير شهيدا» ففرح جدا وتعزت نفسه وتوجه إلى أتريب قرب بنهاء واعترف أمام الوالي بالسيد المسيح. فعذبه كثرا. ثم أرسله إلى لوقيانوس والي الإسكندرية وفي الطريق ظهر له السيد المسيح وعزاه وقوا فابتهجت نفسه جدا. أما لوقيانوس فحاول ولم يفلح » فعذبه كثرا. وأخرا أمر بقطع رأسه فنال إكليل الشهادة. ولما مع أهل بلدته أخذوا جسده ودفنوه بكرامة بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":9,"t":["استشهاد الأب القديس الأنبا بيسورة الأسقف"],"b":"في مثل هذا اليوم استشهد الأب القديس الأنبا بيسورة أسقف ميصيل \"\". وذلك في عهد الإمبراطور دقلديانوس.\nحين علم هذا الأسقف أن دقلديانوس كفر وعبد الأوثان وأعلن الاضطهاد على المسيحيين؛ جمع شعبه وأوصاهم أن يثبتوا على الإيمان المستقيم » ثم ودعهم واتفق مع ثلاثة آخرين من إخوته الأساقفة وهم الأنبا بيسيخوس والأنبا فاناليخوس والأنبا تادرس. ومضوا إل الوالي واعترفوا بالسيد المسيح عن الإيمان المسيحي. فعذبهم الوالي عذابا شديدا لا سيما لما علم أنم أساقفة وآباء للمسيحيين ليجعلهم عبرة ولما فشل الوالي أمام ثباتهم أمر بضرب أعناقهم فنالوا أكاليل الشهادة.\nأما جسد القديس بيسورة فوضع بشبين القناطر إحدى مراكز محافظة القليوبية ثم نقل إلى كنيسة مار جرجس بقصر الشمع '\" ميصيل: هي حاليا مليج مركز شبين الكوم ممحافظة المنوفية.\nسسسب ات “اج سس . ...ا لإ > >>> >> »بي وفيه أيضا من سنة 17 للشهداء ( م ) استشهد الأسقفان الأنبا بيليوس والأنبا يلوس وبصحبتهما إيليا الكاهن وواحد من أ لأراخنة : وذلك أنهم كانوا منفيين إلى بلاد فلسطين.\nوكانوا هناك يعملون في محاجر في تلك الجهات. فتمكنوا مع آخرين من مواطنيهم أن يبنوا بعض الكنائس ولما علم الوالي بذلك» أرسل إلى الملك جالريوس يخبره بذلك. فأمر الملك بتعذييهم. فأرسل الوالي هؤلاء الأربعة إلى فينون في بترا ببلاد فلسطين. حيث ألقوهم في النيران فاحترقوا ونالوا إكليل الشهادة. | ولربنا المجد دائما أبديا آمين."},{"d":10,"t":["استشهاد القديسين يوأنس المصري وزملائه","استشهاد القديسة مطرونة","تذكار استشهاد القديسة باسين وأولادها الثلاثة"],"b":"- في مثل هذا اليوم استشهد القديس يوأنس المصري وزملاؤه وذلك في عهد الإمبراطور مكسيميانوس دازا الذي حكم ما بين سنة 6 ؟ إلى سنة كان هذا القديس يحب الرب من كل قلبه ويحفظ الأسفار الإلهية حتى انطبعت في وقد تقابل معه يوسابيوس القيصري أبو التاريخ الكنسي فدهش من معرفته الواسعة للكتاب المقدس. وقد اعترف هذا القديس مع زملائه بالسيد المسيح أمام الوالي. فأمر في أشغال شاقة. تحت هيب الشمس المحرقة.\nأما يوأنس فأمر الوالي بقلع عينيه وحرق إحدى ساقيه بالحديد وأخيرا أمر بقطع رؤوسهم جميعا » فنالوا أكاليل الشهادة.\nبركة صلواتهم فلتكن معنا أمين.\n\"- وفيه أيضا استشهدت القديسة مطرونة. وقد نشأت في بيت مسيحي. ولما كبرت اضطرتا الحياة أن تعمل كخادمة في بيت امرأة يهودية. وكانت سيدا تغريها على اعتناق الديانة تكن مطرونة ة تستمع إلى مشورتها. لذلك كانت عليها الخدمة وتضريا وفي أحد الأيام حبستها في مظلمة وتركتها أربعة أيام بدون أكل أو شرب. ثم 0 أخرى. فتتيحت فيه؛ .\nونالت إكليل الشهادة لأجل تمسكها بيما بركة صلواتها فلتكن معنا: ف أيضا تعيد وأولادها الثلاثة.\nتعيد الكنئيسة بتذكار استشهاد القديسة باسين بركة صلواتهم فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":11,"t":["استشهاد القديس واسيليدس الوزير 0","استشهاد الثلاثة فلاحين بإسنا"],"b":"عد عد ... ..\nفي مثل هذا اليوم استشهد القديس واسيليدس وكان وزيرا في عهد الملك نوماريوس الذي تزوج أخت واسيليدس. وكان هما يوسابيوس ومكاريوس. ولما ثار الفرس على الروم أرسل الملك نوماريوس ابنه يسطس لقاتلة الفرس.\nأما الملك نوماريوس فقتله صهره آيروس. فقام دقلديانوس خادم الملك نوماريوس وقتل آيروس» فالتف الجنود حوله وأقاموه ملكا في أنطاكية سنة 7/84 م. وبعد فترة كفر بالمسيح وعبد الأوثان وأصدر منشورا باضطهاد المسيحيين في 77 فبراير سنة وبدا بقتل أفراد العائلة المالكة. فأرسل واسيليدس إلى ماسورس والى الخمس مدن الغربية» الذي عذبه عذابا تارة بالهنبازين 7 » وتارة بوضعه في خلقين \"\" ثم رفعه على لولب به منشار حديد. ولم يترك شيئا من أنواع العذاب إلا وعذبه به ولما رأه ثابتا كالصخر على إيمانه بالسيد المسيح 6 أمر :\nبقطع رأسه » فنال إكليل الشهادة.\nبركة صلواته فلتكن معنا أمين.\nالهنبازين آلة عبارة عن دولاب به أسنان من حديد لتمشيط الجسم.\nالخلقين إناء ضخم من النحاس يغلى فيه زيت أو قار.\nلين وفيه أيضا استشهد القديسون الثلاثة الفلاحين بإسنا وهم سورس وأنطوكيون ومشهوري وذلك أنه بعد استشهاد شعب إسناء أخذ الوالي إريانوس» الأنبا أمونيوس أسقف إسنا أسيرا معه إلى أسوان وعند رجوعه دخل مدينة إسنا فلم يجد فيها وسار إلى بحري المدينة فقابله هؤلاء الفلاحون الثلاثة؛ فصرخوا بصوت واحد نحن مسيحيون 6 أجاب الوالي لقد إلى أغمادها . فقالوا معنا فؤوسناء اقتلنا بها. فأمر الوالي الجند بقتلهم » وكان هناك حجر كبير » مدوا عليه أعناقهم » فقطع الجند رؤوسهم بفؤوسهم ونالوا أكاليل الشهادة » ومازالت أجسادهم موجودة ق مقصورة جميلة ف مدينة إسنا.\nبركة صلواتهم فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":12,"t":["تذكار رئيس الملائكة الجليل ميخائيل","تذكار انعقاد المجمع المسكونى بأفس","نقل أعضاء القديسين إقليمس وأصحابه"],"b":"جججهيجوجوجوهون - في مشل هذا اليوم تعيد الكنيسة بالتذكار الشهري لرئيس الملائكة الطاهر ميخائيل رئيس جند الرب.شفاعته المقدسة فلتكن معنا آمين.\n7 - وفيه أيضا من سنة /149 للشهداء ) انعقد المجمع اللسكوني أفسس بأسيا الصغرى من مائق أسقف 6 بأمر أ لإمبراطور الصغير : للنظر ق بدعة نسطور أسقف القسطنطينية الذي قال: ( إن القديسة مريم لم تلد إلها متجسدا بل إنسانا عاديا؛ حل فيه بعد ذلك ابن الله حلول المشيئة والإرادة لا حلول الاتحاد وإن .\nللسيد المسيح طبيعتين وأقدومين )» ولذلك قال: ( لا يجوز تسمية العذراء والدة الإله ). ومن أجل هذه البدعة الخطيرة؛ اجتمع هذا لمجمع برئاسة البابا القديس كيرلس الأول عمود الدين بطريرك الإسكندرية الرابع والعشرين ومعه خمسون أسقفا مصريا والقديس الأنبا شنوده رئيس المتوحدين» والقديسن الأنبا بقطر رئيس أديرة الأنبا باخوميوس أب الشركة» والقديس ديوسقوروس مدير مدرسة الإسكندرية اللاهوتية وسكرتير البابا. وقد حاول نسطور أن يعطل انعقاد المجمع» ولكنه أخيرا اضطر للحضور» ومعه بعض أساقفته به رجال مسلحون لإرهاب المجمع.\nولما سأله البابا كيرلس وأعضاء المجمع عن تعاليمه رد قائلا:\nإن العذراء مريم ولدت إنسانا محضا ولم تلد الإله المتأنس . ولما حاول المجتمعون أن يردوه عن رأيه الفاسد ؛ تمسك بكفرى فحكم المجمع بقطعه وإبعاده عن كرسيه » وحرم كل من يعتقد باعتقاده. ثم ناه الإمبراطور إلى أخميم بصعيد مصر حيث مات شر ميتة.\nثم أثبت المجمع أن العذراء هي والدة الإله الكلمة المتجسد \".\nووضعوا مقذمة قانون الإيمان ( نعظمك يا أم النور الحقيقي... ) ووضعوا ثمانية قوانين كنسية أخرى.\nومن أسباب انعقاد هذا المجمع أيضا بدعة بيلاجيوس» الذي كان يقول أن خطية آدم كانت قاصرة عليه وحده ولم تتسرب إلى من بعده. ومن ثم فكل إنسان يولد يكون كادم قبل الخطية. وبمكده أن يبلغ أسمى درجات القداسة بجهاده الطبيعى وبعد أن ناقش المجمع بيلاجيوس البتدع؛ وأظهر بطلان تعاليمه؛ حرمه المجمع» كما بين المجمع أن الإنسان لا يكون كاملا إلا بنعمة الخلاص بدم المسيح.\nبركة صلوات آباء هذا المجمع فلتكن معنا آمين.\n- وفيه أيضا تيد الكنيسة بنقل أعضاء الشهداء إقليمس وأصحابه إلى مدينة الإسكندرية.\nبركة صلواتهم فلتكن معنا. ولربنا امجد دائما أبديا آمين.\nالي استند عليها المجمع لإثبات أن العذراء هي والدة الإله المتجسد هي: ( لو : 35 لو ان 4 إش لان نا إش 1:4 )."},{"d":13,"t":["تذكار الأعجوبة التي صنعها القديس باسيليوس الكبير أسقف قيصارية الكبادوك","نياحة البابا متاؤس الثاني البطريرك التسعين من بطاركة الكرازة المرقسية"],"b":"بوووجوجووويوجووهون هن - في هذا اليوم تذكار الأعجوبة الت تمت على يد القديس باسيليوس الكبير. حيث أن شابا بمدينة قيصرية أحب ابنة سيده.\nولما كان زواجه منها مستحيلا. لج إلى أحد السحرة. فكتب له وأمره أن يذهب في منتصف الليل إلى قبور غير المؤمنين؛ يده بالورقة؛ فيتناولها منه الشيطان» وطلب منه أن يكفر بالمسيح إذا نال أمنيته» فوافقه الشاب على ذلك. وتمم له الشيطان ما قصده» بأن ألهب قلب الشابة بهواه حتى تزوجته.\nكشف الله الغشاوة عن عقلهاء وعرفت أن ذلك الشاب غير مسيحي لأنه لا بمارس أي عبادة مسيحية؛ على ما فعلت. ولما سألته عن السبب صارحها بكل ما الفتاة إلى القديس باسيليوس وقصت عليه .\nقصتها وطلبت منه نجدتها. فاستحضر الشاب وسأله إن كان يريد أن يرجع إلى السيد المسيح فوافق. فاستبقاه عنده لمدة ثلاثة أياء وأمره أن يصلى خاالما. وبعدها افتقده. فأعلمه الشاب أن الشياطين تهدده بذلك الصك الذي كتبه على نفسه» فشجعه.\nوظل الشاب ق مكانه أربعين يوما وهو يصلى. ثم افتقده القديس باسيليوس وسأله عن حاله» فأعلمه الشاب أنه رآ في تلك الليلة يقاتل عنه الشيطان وقد غلبه.\nوفي الغد أحضر القديس باسيليوس الشعب المسيحى إل الكنيسة» وطلب إليهم أن يصرخوا إل الله قائلين يارب ارحم.\nفي صراخهم»؛ حت رأوا ورقة تسقط من فوقء وكانت هي الصك الذي أخذه الشيطان على ذلك الشاب.\nالقديس باسيليوس على الشعب. ثم بارك على الشاب.\nوأمره ألا يعود إلى ذلك مرة أخرى. ثم ناوله من الأسرار المقدسة وأعاده إل زوجته وبارك عليهما. | بركة صلاة القديس باسيليوس فلتكن معنا آمين.\n\" - وفيه أيضا من سنة 87 للشهداء ( ) تنيح البابا متاؤس الثاني البطريرك التسعون من بطاركة الكرازة المرقسية.\nكان هذا البابا راهبا بدير القديسة العذراء الشهير بالمحرق باسم ( متى الصعيدي ) ولما تنيح البابا يوأنس الحادي عشر الشعب واتفقوا على اختياره لكرسي البطريركية : ور#مموه بطريركا باسم الأنبا متاؤس الثاني يوم 7 توت سنة 64 للشهداء ( 97 م ». وذلك ق أياء السلطان فخر الدين عثمان الذي كانت تربطه به مودة كبيرة. وقد أقام هذا البابا كأسلافه بكنيسة القديسة العذراء الأثرية بحارة زويلة بالقاهرة. وقد رسم مطرانا للحبشة باسم الأنبا غبريال : وكذلك عمل الميرون ريف الملقدس بكئيسة القديسة العذراء بحارة الروم بالقاهرة مع ستة من الأساقفة. | وقد جلس هذا البابا على الكرسي المرقسى مدة ثلاث عشرة سنة» كانت كلها سلام. وبعد أن أكمل جهاده تنيح بسلام ى| ودفن بدير الخندق المعروف حاليا بدير الأنا رويس.\nبركة صلواته فلتكن معنا. .\nولربنا المجد دائما أبديا آمين.\nوني"},{"d":14,"t":["نياحة القديس أغاثون العمودي","استشهاد القديس فيلكسن وريجولا أخته والقديس أكسيوبرا نتيوس"],"b":"مثل هذاا ليوم من سنة 20 للشهد اء بلا م 4 تنيح ال ب القديس أغاثون العمودي وقد كان هذا القديس من مديئة تانيس '. وكان أبوه يسمى مطرا وأمه مريم. وكانا قديسين محبين للعطاء. فشب هذا القديس محبا لله » وكان يميل إلى حياة الرهبنة ولكنه رسم قسا فلازم البيعة مداوما على الصلوات نهارا وليلا. وكان يخدم شعب الله بكل محبة وأمانة. وكان يطلب من السيد المسيح أن يسهل خروجه من هذا العالم لي ليمضى إلى البرية. فاستجاب له السيد المسيح. وظهر له ملاك الرب في زئ ورافقه إلى البرية؛ حتى أوصله إل دير الأنبا مكاريوس الكبير وهناك التقى بالقديسين أبرآم وجورجى وتتلمذ لهما مدة ثلاث سنوات فألبساه شكل الرهبنة؛ فصار يجاهد في حياته النسكية بأصوام وصلوات مدة سبع سنوات» وكان مداوما على القراءة خاصة في سيرة القديس سمعان العمودي » فاشتاق أن يتمثل به. فترك شيهيت بعد استكئذان آباء الدير ومضى إلى )0 تائيس مدينة مصرية قليمة كانت تسمى صوعن - ذكرها إشعياء الني - وحزقيال الني ا 5 صار امعها تانيس. 5 تغير إلى صا الحجر وهي موجوده اليوم ق محافظة نواحي سخاء وأقام في كنيسة صغيرة إلى أن بنى له المؤمنون مسكنا صغرا على شبه عمود» فصعد إليه ومكث به. وقد صنع الله على يديه آيات كثيرة وكانت الشياطين تحاربه وكان ينتصر عليها بالصلاة ورشم الصليب.\nعاش هذا الأب ماثة سنة. . أقام منها ته سنة ف العالم؛ وخمس سنوات كاهنا بتانئيس؛ وعشر سنوات ببرية شيهيت؛ ثم سنة فوق العمود في سخا.\nولما أراد الرب أن يريحه من أتعاب هذا العالم مرض قليلا وأسلم روحه بيد الرب.\nبركة صلواته فلتكن معنا. آمين.\n\"- وفيه أيضا من سنة للشهداء ), استشهد القديس فيلكس وريجولا أخته والقديس أكسيوبرانتيوس. كانوا من مدينة طيبة بالصعيد. انضم فيلكس وأكسيوبرانتيوس إلى الفرقة الطيبية التي كان يرأسها القديس موريس» أما ريجولا فقد ولما تمسكت الفرقة بإيمانها بالسيد المسيح؛ نصحهم القديس موريس أن يرحلوا من أجونام إلى زيورخ ونشروا فيها الإيمان المسيحي. إلا إن الإمبراطور مكسيميانوس كان قد قتل الفرقة وأخذ يتعقب كل 2 له صلة بهماء فقبض الوالي على الثلاثة» واعترفوا أمامه نهم المسيحي وبصلتهم بالقديس موريس»؛ فعذبهم عذابا شديدا حق ينكروا الإبمان : فلم يتزعزعوا : بل حدثت عجائب كثيرة أثناء العذاب. منها شفاء ريجولا وعودتها حية بعد وضعها في خمع مغلي وإجبارها على شرب رصاص منصهر» فآمن كثيرون. وكانوا يسمعون صوتا من السماء يقول لهم \" لا تخافوا ها أنا معكم؛ احتملوا ولتتقوا قلوبكم لأن ساعة دعوتكم قد أنت والأكاليل معدة»؛ وسيكون لكم مجد عظيم وسط صفوف \".\nبعد ذلك أمر الوالي بقطع رؤوسهم» إلا أن الثلاثة قاموا وحملوا رؤوسهم في أيديهم وساروا نحو مسافة ستة وعشرين ثم ركعوا ورقدوا مرة أخرى. فكفنوهم ودفنوهم وبنوا كنئيسة على إ حمهم ق زيورخ لا تزال باقية. كما أقيمت على ل امهم كئيسة في مكان الاستشهاد بزيورخ ' ' أيضا. وكذلك 1 قيم دير ضخم للراهبات به كئيسة مكرسة باسمهم وإليه ثقل ض من ر فا تهم.\nأما بقية الرفات فثقلت ل سنة إلى كئيسة إ لرسولين بطرس وبولس في مدينة أندرمات بسويسرا ولا زال باقيا حتى بركة صلواتهم فلتكن معنا :\nولربنا المجد دائما أبديا أمين.\nمقاطعة بسويسرا اختارت هؤلاء القديسين شعارا لهاء كما إن ختم برلمان هو صورة القديسين الثلانة وكل منهم يحمل رأسه على يديه 0"},{"d":15,"t":["نقل جسد القديس إسطفانوس","نياحة الأنبا ألناسيوس القوصي"],"b":"- في هذا اليوم تعيد الكنيسة بنقل جسد القديس إسطفانوس رئيس الشمامسة وأول الشهداء. وذلك أنه بعد استشهاده في أورشليم أخذ رجال أتقياء جسده الطاهر ودفنوه ق ضيعة يقال لها غملائيل بالقرب من أورشليم. وظل جسده مجهولا حوالي ثلاثمائة سنة. ثم ظهر لكاهن يدعى لوكيانوس وعرفه بنفسه فمضى الكاهن إلى القديس يوحنا أسقف أورشليم وأخبره بذلك. فقام وبصحبته اثنان من الأساقفة وبعض الشعب وحفروا ف المكان المعين » فحدث زلزال عظيم :\nثم ظهر تابوت فيه الأعضاء المقدسة» فحملوه بإكرام عظيم حى أدخلوه أورشليم : شم شيد له أحد أهال القسطنطينية ييدعى الكسندروس كنيسة عظيمة بأورشليم ووضع الجسد فيها. وبعد خمس سنوات تنيح الكسندروس فدفنته زوجته بجانب تابوت القديس إسطفانوس. وبعد ثماني سنوات أرادت هذه المرأة أن تذهب إلى القسطنطينية لتعيش هناك وأرادت أن تأخذ جسد زوجها معها. فأنت إلى الكنيسة وأخذت التابوت الذي به جسد | القديس إسطفانوس ظ منها أنه جسد زوجهاء وكان ذلك من الله. ولما ركيت المركب وسارت ق وسط البحر ردي أصوات تسبيح وترتيل من داخل التابوت : فتعجبت التابوت فعرفت أنه التابوت الذي به جسد القديس إسطفانوس. فشكرت الله على ذلك وواصلت المسير حتى وصلت إلى القسطنطينية وأعلمت الملك قسطنطين بالخرء فخرج هو والبطريرك والأساقفة والكهنة وشعب المدينة وحملوا التابوت على أكتافهم» وفي الطريق توقف الموكب فجأة بعد أن سمعوا صوتا يدوى قائلا: ( هنا يجب أن يوضع جسد القديس ).\nفأمر الملك أن تبنى له كنيسة في ذلك المكان ووضعت فيه الأعضاء المقدسة.\nبركة صلواته فلتكن معنا آمين\n\" < وفيه أيضا تنيح السراج المنير الأنبا أثناسيوس القوصى. كان هذا الأسقف ابن القس الفاضل والمعلم الماهر صليب من أهالي غرب قمولا. وترهحب في دير الشهيد مار بقطر الصحراوي المعروف بدير الكولة بحاجر غرب قمولا ( دير مار بقطر بنقادة ).\nورسم أسقفا على قوص بيد البابا يوأنس العاشر البطريرك ال 8 في حوالي مسنة وقد شارك في تجليس الأنبا تيموثاوس أسقف إبريم وأبو خراس ( النوبة ). واهتم بالحفاظ على اللغة القبطية فوضع مقدمة باللهجتين الصعيدية والبحيرية في علم التفسير؛ ووضع كتابا عن الأحوال الشخصية : واخر عن تكريس الممرون.\nمع البابا غبريال الرابع سنة 74 2 ف تكريس 0 الملقدس بدير القديس مكاريوس. وله أيضا كتاب وهو شعر باللغة القبطية الصعيدية مقفى في سنة باسم الثلاثية يبلغ مجموع هذه الأبيات 774 بيتاء شخصيات من الكتاب المقدس وبعض القديسين وطرفا من أمجاد الماضي القديم. وله عدة قوانين خاصة بالزواج» والمعمودية» وتكريس الميرون» وفي الكهنوت» وفي حكم الزناء وقوانين البيع والشراء؛ وفي ختان فكان هذا الأب المبجل والعامل الرابح سراج عصره المنير وتنيح في قوص في اليوم الخامس عشر من شهر توت.\nبركة صلواته فلتكن معنا .\nولربنا المجد دائما أبديا آمين."},{"d":16,"t":["تكريس كنيسة القيامة بأورشليم"],"b":"مثل هذا اليوم من سنة 50 للشهداء 97 م تم تكريس كئيسة القيامة بأورشليم. وذلك أنه بعد أن اكتشفت الملجة هيلانة خشبة الصليب» أمرت ببناء كنيسة القيامة» فتم بناؤها ا على أحسن - ولما اكتمل البناء» أرسل الإمبراطور قسطنطين إلى البابا ألناسيوس بطريرك الإسكندرية وإلل بطريرك القسطنطينية وبطريرك أنطاكية 6 ليذهبوا إلى أورشليم ومعهم أساقفتهم. وهناك استقبلهم القديس مكاريوس أسقف أورشليم. وكرسوا كنئيسة القيامة. وف اليوم التالي طافوا بالصليب المقدس داخل الكنيسة وبقية ية المواضع المقدسة. اشم عادوا إلى كراسيهم بسلام.\nبركة صلواتهم فلتكن معناء ولربنا المجد دائما أبديا آمين."},{"d":17,"t":["تذكار الاحتفال بالصليب المجيد في كنيسة القيامة","استشهاد القديس قسطور القس","نياحة القديسة اؤغنسطا","نياحة القديس المعلم جرجس الجوهري"],"b":"- في مثل هذا اليوم من سنة 01 للشهداء ( 0 ) احتفل بطاركة الكنائس المسيحية وهم البابا القديس أثناسيوس الرسولي بطريرك الإسكندرية» وبطريرك القسطنطينية» وبطريرك أنطاكية» والقديس مكاريوس بطريرك أورشليم. بأن طافوا بالصليب المجيد في كنيسة القيامة باحتفال عظيم وسجدوا للرب» وأقاموا الصلوات والقداسات» ومجدوا الصليب» ثم وضعوه في الموضع المخصص له داخل خزانة من الفضة.\nهذا العيد أيضا ظهور علامة الصليب المجيد للإمبراطور قسطنطين الكبير» وهو ذاهب لمحاربة الطاغية بن مكسيميانوس سنة وذلك أنه رأى أثناء في السماء ومعه الضباط والجنود» علامة الصليب المجيد من نور عظيم أبمي من نور الشمس» وتحت الصليب كلمات:\n( بهذا تغلب ) فتشجع وتشدد وانتصر في الحرب بقوة الصليب مما كان له أبلغ الآثر في قبوله الإيمان المسيحي.\nبركة الصليب المجيد فلتكن معنا امين.\nليف كثيرة أثناء سجنه وتعذييه أرسله إلى والى قرية جم ركز مطاى محافظة المنيا. ©\" مره قرية تابعة لمركز ب مزار - محافظة المنيا.\n7 - وفيه أيضا استشهد القديس أبا قسطور القس في أيام الإمبراطور دقلديانوس في القرن الرابع الميلادي. ولد هذا القديس في قرية بردنوها \"؟ بصعيد مصر من أبوين مسيحيين» وقد ربياه على الفضيلة والتقوى. رسم شماسا ؛ فلازم البيعة. بعد ذلك: تزوج سا على كنيسة بلدته» فرعى الشعب أحسن رعاية.\nوقد أنجب ابنا أسماه أفراهام على اسم والده؛ وابنة اسمها كبر القس قسطور ف العسر وأصبح كاهنا وقورا ذا شيية وكان محبوبا من شعبه. ولما أثار دقلديانوس الاضطهاد على المسيحيين» أخذ قسطور القس بجول بين شعبه يثبتهم على الإبمان المستقيم. وذهب إلى بلدة القيس ”\" عاصمة المنطقة من بلدته» ليفتقد المسيحيين المسجونين بسبب إيمانهم بالمسيح» وكان يثبتهم ويشجعهم ولما بلغ الوالي أن القس قسطور يشجع المسيحيين على الثبات في الإيمان وعدم السجود للأوثان» أمر بالقبض عليه وإحضاره مع المسجونين للتعذيب الشديد. فعذبوه بكل أنواع العذاب وكان الرب يعزيه ويقويه ويشفيه. بعد ذلك أرسله الوالي إلى والى مصر القديمة وكان اسمه كلكيانوس ليعذبه. وبعد أن عذبه كثيرا وظهرت منه معجزات الإسكندرية » فعذبه هو أيضا بشدة. ثم سقاه سما مميتا فلم لأنه رشم الكأس بعلامة الصليب قبل أن يشربه. ولما تعب من تعذيبه أمر بقطع رأسه» وكان عمره في ذلك الوقت يقرب من ماثة وعشر سنين. وبينما هو يصلى قبل تنفيذ الحكم ناداه صوت من السماء قائلا: يا حبيي قسطور تعال إل موضع ثم قطعوا رأسه» فنال إكليل الشهادة. وقام القديس يوليوس الأقفهصي بكتابة سيرته وتكفين جسده وأرسله إلى بلدة بردنوها. وهناك استقبله أهلها بالتسابيح والألحان. وحملوه إلى بيته حت انقضى زمن الاضطهاد» فبنوا كنيسة على اسمه كرست في اليوم السابع عشر من شهر أمشير.\nبركة صلواته فلتكن معنا. آمين.\n: 7< وفيه أيضا تتحت القديسة ازغنسطاء وذلك في أيام الملكين أركاديوس وأنوريوس وكانت تقيم بدير بالقرب من روماء فوقعت أسيرة في يد رجال حاكم الرهاء حيث قدموها له؛ زوجة الحاكم كجارية لا.\nالرب طريقها وأعطاها نعمة في عيني سيدتهاء فأقامتها رئيسة على كل العاملات بالقصر. أما هي فكان قلبها متعلقا بالحياة السماوية؛ تمارس نسكها وصلواتها يجهاد عظيم.\nوحدث أن تعرض ابن الحاكم لمرض شديد» وفشلت كل الأطباء في شفائه؛ فطلبت أمه سيدتها من ريف ل عمجب اؤغنسطا أن تصلى لأجله » فبسطت يديها وصلت إل الله أن يتمجد في هذا الابن الوحيد لأجل خلاص الكثيرين. ولما انتهت من صلاتها شفي الطفل في الحال» فحررها الحاكم من وأعطى لها مكانا منفردا كطلبها فأقامت متعبدة فيه لله بلا انقطاع. ض وبعد أيام قليلة مرضت زوجة الحاكم» فطلبت اؤغغسطا الله نعمة الشفاء بصلاتها.\nثم خرج الحاكم إلى البرية ذات يوم» ليصطادء فضل تذكر القديسة اؤغخسطاء وكيف تلتجىء إلى السيد المسيح في الضيقات» وترشم ذاتها بعلامة الصليب؛ قوة إلهية. فصرخ الحاكم» وطلب من السيد المسيح إله أن ينقذه. وإذ به يرى علامة الصليب من نور حتى دخل المدينة. ففرح به شعبه واستدعوا القديسة لكي تبشرهم بالإيمان بالسيد المسيح. فتهللت جدا بالإيمان. وطلبت من الحاكم أن يرسل إلى الإمبراطور لكي يرسل لهم كاهنا تقيا؛ فأرسل لهم قسا يدعى الذي صار يكرز مجاهدا بالإيمان حتى آمن الجميع.\nأسقفا على الرها كطلب الحاكم والشعب.\nوكانت القديسة اأغنسطا تقوم بخدمة الدساء. وسمج الله لا برض قصير وتضحت بسلام. . .\nبركة صلواتها فلتكن معنا آمين.\nوفيه أيضا من سنة 909 للشهداء ( م تنيح القديس جرجس الجوهري. كان المعلم جرجس الجوهري من مشاهير الأقباط في أواخر القرن الثامن عشر وأوائل القرن التاسع عشر.\nوهو شقيق المعلم إبراهيم الجوهري \"\". وقد تربى مثل أخيه في كتاب مدينة قليوب كنظام ذلك العصر. فتعلم القراءة والكتابة على العلوم الدينية واللغة القبطية. ولما كبر المعلم إبراهيم» الذي كان يشغل منصب رئيس كتاب مصر”؟ في الأعمال والأمور الكتابية. فكان له خبر معلم وأفضل مرشد. وكانت ملازمته لأخيه ذات أثر فعال في حياته 6 وسبا ج مجاحه » عندما تقلد منصب رياسة 0036\" بعد نياحة أخية المعلم إبرا هيم الجوهري.\nوقد باشر المعلم جرجس شكئون بيب\" ف أربعة عهود في حكم المماليك» ومدة حكم الحملة الفرنسية؛ ومدة حكم الأتراك» ثم أول حكم محمد على باشا.\nوقد لاقى شدائد كثيرة» وكان عظيم النفس» كربما في يوزع على الفقراء والمساكين والكنائس والأديرة الأموال الكثيرة خصوصا في المناسبات.\n)0 نياحة المعلم إبراهيم الجوهري يوم بشنس.\nرئيس المباشرين: وظيفة تشبه وظيفة رئيس الوزراء حاليا.\nرئيس كتاب مصر. : وظيفة تشبه وظيفة رئيس الوزراء حاليا.\n| حى الآن وفوقه كنيسة صغيرة ة يصلى فيها ق تذكاراتهما.\nكما إنه ساعد البابا مرقس الثامن في بناء الكنيسة المرقسية الكبرى بالأزبكية ومقر البطريركية المجاور لهاء من أملاكه أخيه الذي كان قد حصل قبل نياحته على فرمان من الباب العالي ببنائها. هذا وقد عينه البابا مرقس الثامن ناظرا على كثير من كنائس القاهرة ومصر القديمة وذلك لحبته والعناية مها.\nمرض المعلم جرجس في أواخر حياته؛ ثم تشيح بسلام؛ ودفن بجوار شقيقه في المدفن الخاص بهما بجوار كنئيسة مار جرجس بدرب التقا بمصر القديمة. ولا يزال قيرهما موجودا صلوات هذا الأرس القديس فلتكن معناء ولربنا المجد دائما أبديا آمين."},{"d":18,"t":["ثاني يوم عيد الصليب","استشهاد القديس بروفوريوس","استشهاد القديس إسطفانوس القس والقديسة نيكيتي"],"b":"- في هذا البوم تعيد الكئيسة بتذكار اليوم الثاني لعيد الصليب المجيد. ويصلى بالطقس الشعانينى والفرايجى.\nبركة الصليب المجيد فلتكن معنا آمين.\n7- وفيه أيضا استشهد القديس بروفوريوس» وكان في أول حياته وثنيا في عهد الملك الإمبراطور يوليانوس الجاحد, الذي في يوم مولده أقام حفلا كبيرا لعظماء مملكته وأحضر رجال الملامي لإحياء هذا الحفل وكان بينهم بروفوريوس؛ فأمره الملك أن يستهزئ بطقوس المسيحيين. فقام بتمثيل بعض وعندما وصل إلى طقس المعمودية رشم علامة الصليب على الماء. فأضاء الرب بصيرته فرأى نعمة إلطية قد حلت على الماء ونورا عظيما قد غشاه. فغطس في الماء ثلاث مرات ثم صعد منه ولبس ثيابه» وأقر أنه مسيحي. فحسب الحاضرون ذلك أنه أحد أدوار التمثيلية؛ لكن بروفوريوس صار يصيح بشدة أنا مسيحو . فاندهمش الملك وكل الحاضرين حينما رأوه جادا في حديشه. فبدا المللك يلاطفه واعدا إياه بعطايا جزيلة 6 ولما 1 يفلح ق إرجاعه عن الإبمان بالسيد المسيح» أمر بقطع رأسه فال إكليل الشهادة.\nبركة صلواته فلتكن معنا آمين.\n- وفيه أيضا تعيد الكنيسة بتذكار استشهاد القديس إسطفانوس القس والقديسة نيكيق.\nبركة صلواتهما فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":19,"t":["اليوم الثالث من أيام عيد الصليب المجيد","تذكار إصعاد القديس غريغوريوس الأرمني من الجب"],"b":"تحتفل الكئيسة البوم : باليوم الثالث والأخير من أيام عيد الصليب المجيد 6 ويصلى بالطقس الشعانيني والفرايجي.\nوفي هذا اليوم تعيد الكنيسة بتذكار إصعاد القديس غريغوريوس الأرمني من الجب» وقد ولد هذا القديس من سلالة ملكية في أرمينيا » ومات والده مقتولا » فبقى غريغوريوس مع أخيه؛ بهما مربيتهما إلى قيصرية الكبادوك» حيث قامت في حياة التقوى والقداسة. وكان غريغوريوس يتحلى بالفضائل مع نبوغه في العلم والفلسفة » ثم خدم في بلاط ابن الملك تريداته. وفي أحد الأيام أ مره الملك أن يقدم ذبيحة للأوثان فأخبره غريغوريوس بأنه مسيحي. فغضب الملك وأمر بتعذيبه وكان الرب يخلصه ويشفيه. أخيرا أمر الملك بإلقائه في جب عميق ليموت فيه جوعا وعطشا. فحفظه الله في الجبء وأعد له سيدة عجوزا أبصرت في رؤيا من يقول لها اصنعي خبزا وألقيه في هذا الجب. فكانت تفعل ذلك لمدة أربعة عشر عاما.\nمرض الملك مرضا شديدا » فظهر ملاك الرب لأخته وأعلمها أن أخاها لن يبرأ مالم يصعد غريغوريوس من الجب. وفي الصباح أخيرت رجال الدولة بما رأت, فألقوا حبلا ليرفعوا دانيال الجديد من الجب حيا؛ فاستقبلته الجماهير باحتفال عظيم. . وطلبت منه أخت الملك أن يصفح عن عن أخيها ويصلى من أجل شفائه» فاستجاب له الرب وشفي الملك مع ترك علامة أما بقية جهاده ونياحته فمذكوران تحت اليوم الخامس عشر بركة صلواته فلتكن معنا ولربنا المجد دائما أبديا آمين\nلقف"},{"d":20,"t":["نياحة البابا أثناسيوس الثاني البطريرك الثامن والعشرين من بطاركة الكرازة المرقسية","استشهاد القديسة ملاتينى العذراء"],"b":"نياحة القديسة اؤيستى. - - في هذا اليوم تعيد الكنيسة بتذكار نياحة القديسة اؤبستى؛ وكانت قد تزوجت ورزقت بولد ثم مات زوجها وهي ما تزال شابة ؛» فنذرت أن تقضى بقة حياتها فق العبادة واللسك وتربية ابنها في مخافة الله. فسلكت السيرة الروحانية مواظبة على الصوم.\nوالصلاة والميطانيبات ثم مضت إلى الأنبا مكاريوس أسقف نيقيوس ''ء وسألته أن يلبسها إسكيم الرهبنة فأشار عليها أن نفسها لمدة سنة. فمضت إلى بيتها وحبست نفسها في حجرة وأخذت تمارس الحياة النسكية باجتهاد عظيم. وانقضت السنة ونسى الأب الأسقف طلبها. فرأى ذات ليلة القديسة في شكل مضيء وسمعها تقول: ( لماذا نسيتني إلى الآن وأنا سأتنح الليلة ). ورأى نفسه في الحلم أنه قام من نومه وصلى عليها صلاة الرهبنة وألبسها ثوبهاء ولمالم يجد قلنسوة» خلم قلنسوته وألبسها لهاء ثم وشحها بالإسكيم المقدس وكان بيدها صليب من فضة ناولته له قائلة: ( اقبل من تلميذتك هذا الصليب ).\nوللحال استيقظ الأب الأسقف من نومه فوجد الصليب بيده؛ 0 ليقيوس: حاليا زاوية رزين ممحافظة المنوفية .\nطقف فتعجب ومجد الله ؛ ثم قام ومضى هو وتلميذه إلى بيت القديسة فوجد ابنها جالسا يبكي. فسأله عن سبب بكائه فقال إن والدتي نحو نصف الليل وقالت لي ( سأتتح الليلة وأمضى إلى السيد المسيح ) ثم أوصتني قائلة ( احفظ جميع ما يشير به عليك | الأب الأسقف ). ثم تشحت بسلام. فلما سمع الأب الأسقف ذلك» أتى إلى حجرة القديسة وقرع الباب وناداها فلم تجبه فتأكد من نياحتها. فأمر تلميذه بكسر باب الحجرة» ولما دخل وجدها متوشحة بالإسكيم والقلنسوة على رأسهاء فتحقق أن ما راه في المنام حقيقة. فسبح الله ثم كفنها بيديه كعادة وأمر أن يحملوها إلى الكنيسة حيث صلى عليها.\nوكان يوجد بالمدينة رجل وثنى مقعد من أرواح شريرة؛ من جسدها قشفي لوقته؛ وخرج منه الشيطان وقام فأمن لوقته بالسيد المسيح هو وكل بيته واعتمدوا جميعا. وكان كثيرون من المرضى وذوي العامات يأتون إلى البيعة ويلمسون الجسد الطاهر فينالون الشفاء.\nبركة صلاتها فلتكن معنا آمين.\nوفيه أيضا من سنة 117 للشهداء ) تنح الأب المغبوط .\nالأنبا أثناسيوس الثاني البطريرك الثامن والعشرون من بطاركة الكرازة المرقسية. وقد كان هذا الأب وكيلا على كندائس الإسكندرية » فلما تنيح البابا بطرس الثالث البطريرك السابع والعشرون » اتفق رأى الآباء الأساقفة والأراخنة على تقديم يفف هذا الأب بطريركاء لما غرف عنه من الصلاح واستقامة الإيمان. وقد دعي باسم أثناسيوس الصغير تمييزا له عن القديس أثناسيوس الرسولي. وكان ذلك في أيام الإمبراطور زينون.\nوقد اشترك هذا الأب مع أنسطاسيوس قيصرء الذي جاء بعد زينون في إعادة السلام بين كنائس الشرق»؛ بعدما مزق مجمع خلقدونية الكنيسة.\nوعاش هذا البابا فترة هدوء وسلام راعيا شعبه بالبر . والاستقامة. ثم تنيح بسلام. وكانت مدة جلوسه على الكرسي المرقسي حوالي سبع سنين.\nبركة صلاته فلتكن معنا امين.\n- وفيه أيضا تعيد الكنئيسة بتذكار استشهاد القديسة ملاتينى بركة صلواتها فلتكن معنا.\nولربنا المجد دائما أبديا أمين."},{"d":21,"t":["تذكار والدة الإله القديسة مريم","استشهاد القديس كبريانوس الأسقف والقديسة يوستينة"],"b":"- ربت الكنيسة المقدسة أن تعيد في اليوم الحادي والعشرين من كل شهر قبطيء بتذكار والدة الإله القديسة الطاهرة مريم العذراء» كما أن القديسة العذراء صنعت معجزة حل الحديد القديس متياس الرسول من السجن في اليوم الحادي نياحتها في الحادي والعشرين من شهر طوبه» وقد قام بعض الآباء الرسل بتكريس أول كنيسة باسمها في مدينة فيلي في اليوم الحادي والعشرين من شهر بؤونه بعد نياحتها. شفاعتها المقدسة فلتكن معنا. امين.\n\"- وفيه أيضا من سنة 01 استشهد الأسقف القديس كبريانوس والقديسة يوستينة. فكبريانوس هذا كان كافرا وساحراء وقد تعلم السحر ببلاد المغرب حتى فاق على كل كائن هناك ثم حمله فجاء إلى أنطاكية ليرى هناك أعلج منه وإلا عليهم بعلمه. ولما شاع ذكره في تلك المدينة أتاه شاب من أبناء أكابرها كان قد هوى شابة مسيحية عذراء تدعى يوستينة. كان قد رآأها أثناء ذهابها إلى البيعة فالتهب قلبه بهواهاء ولكنه لم يدل منها بغيته لا بالمال ولا بالوعد ولا الوعيد ولا يفف أيضا. وشكا له حاله مؤملا نيل مناه على يديه فوعده وبدأ يعمل جهده بسحره فلم ينجح لأنه كان كلما أرسل إليها قوة من قوى الشياطين فيجدونا قائمة تصلي فيعودون بالخيبة. ولما رأى كبريانوس نفسه عاجزا دعا الشياطين وقال لهم: إن لم تأتوني بيوستينة وإلا فأنا أصير الشيطان حيلة ليخدعه بهاء وذلك أنه أمر أحد جنوده لكي يتزبى بزبها ويظهر في صورتها ويأتيه. ثم سبق فأعلم كبريانوس بمجيئهاء ففرح وظل يرقبها. وإذا بالشيطان المتشبه بها قد دخل إليه ففرح كبريانوس وقام ليعانقهاء ولعظم بها قال لها: مرحبا بست النساء يوستينة. فعند ذكره اسسمها فقط صار الشيطان المتشبه بها كالدخان» وانحل وصار فعلم كبريانوس إنها خدعة من الشيطان الذي لم يستطع أن يقف حيث ذكر اسمها فقط. فقام لوقته وأحرق كتب السحر ومضى فتعمد من بطريرك أنطاكية الذي ألبسه شكل الرهبانية. وبعد قليل رسمه شماسا ثم قسا. ولما نجح في الفضيلة وتقدم في علوم البيعة جعلوه أسقفا على قرطاجنة في سنة 48 فأخذ القديسة يوستينة وجعلها رئيسة على دير للراهبات هناك. ولما اجتمع المجمع بقرطاجنة في سنة كان هذا القديس أحد المجتمعين فيه. ل“ ولما علم بهما الملك ديسيوس استحضرههما وأذاقهما مر الاضطهاد حقى اضطر هذا القديس لأن يترك قرطاجنة مقر كرسيه زمنا ثم عاد يكرز ويعلم ويكتب الكتب إلى أن تولى الملك والبريانوس سنة 0 م وأثار الاضطهاد على المسيحيين :\nوبعد قليل قطع رأسيهما فنا لا إكليل الشهادة .\nبركة صلواتهما فلتكن معنا ولربنا المجد دائما أبديا آمين."},{"d":22,"t":["استشهاد القديسين كوتلاس وأكسوا أخته وتانتاس صديقه","استشهاد القديس يوليوس الأقفهصى كاتب سير الشهداء ومن معه"],"b":"ووو في مثل هذا اليوم استشهد القديسون كوتلاس وأكسوا أخته ابنا سابور ملك الفرس وتاتاس صديقه. وقد كان الملك سابور يعبد الدار والشمس ويضطهد المؤمنين باسم السيد المسيح في بلادة.\nوكان تاتاس رئيسا على إحدى البلاد فوشى به بعض الأشرار عند الملك بأنه مسيحي» فأرسل إليه طوماخر الوالي ليتحقق من عقيدته إن كان الأمر صحيحا ولما سمع الأمير كوتلاس جاء إل صديقه تاتاس الذي قبض عليه الوالي وأمر بطرحه في أتون النار.\nفرشم تآناس النار بعلامة الصليب فانطفأت للحال. فتعجب الأمير كوتلاس وظن أن ذلك بفعل السحرء فأخبره تاناس أنه ' بفعل الإبمان بالسيد المسيح. فقال له الأمير هل أستطيع أن أفعل هكذا إذا أمنت» فأجابه وأكثر من هذا تفعل. فآمن كوتلاس بالسيد المسيح ثم تقدم إلى النار ورشمها بعلامة الصليب فرجعت خمسة عشر ذراعا. فكتب الوالي إلى الملك يعرفه بالأمر» فاستدعى الملك الأثنين وأمر سيافا فقطع رأس تاتاس ونال إكليل الشهادة.\nأما كوتلاس فعذبه بأنواع العذاب ثم طرحه في السجن» وأرسل له أكسوا أخته لكي تثنيه عن عزمه» فوعظها وأمال قلبها إلى الإبمان بالسيد المسيح وأرسلها لأحد الكهنة فعمدها سراء وعادت إلى تقول ليتك يا أبى تحصل على ما حصلت عليه أنا وأخى فإنه ليس إله إلا يسوع المسيح. فغضب الملك وسلمها إلى المعذبين.\nحتى فاضت روحها ونالت إكليل الشهادة. 0 وأخرا ربطوا كوتلاس في أذيال الخيل حتى تحطمت عظامه وفاضت روحه الطاهرة ونال إكليل الشهادة.\nبركة صلواتهم فلتكن معنا آمين.\n\"- وفيه أيضا استشهد القديس يوليوس الأقفهصى \"\". ولد هذا القديس في أقفهص» ولما كبر ذهب لمدينة الإسكندرية وسكن فيها. وكان ذلك أثناء الاضطهاد الذي أثاره دقلديانوس وأعوانه على المسيحيين بصفة عامة» وعلى أقباط مصر بصفة خاصة بالإيمان » وعدم طاعتهم لأوامر الملك بعبادة الأوثان.\nكان يوليوس الأقفهصي غنيا جدا بالأموال والمقتنيات وقد السيد المسيح للعناية بأجساد الشهداء وتكفينهم وارسالهم إلى بلادهم وكان يفعل ذلك بنفسه» كما كان له ثلاثماثة غلام كاتب للأماكن المختلفة لكتابة سير الشهداء وتكفينهم ودفنهم. وقد أنزل الله سهوا على قلوب الولاة فلم بمسكوه؛ لأن الله حفظه سالا لغاية حسنة؛ وهى خدمة القديسين وكتابة يرهم تذكارا للأجيال القادمة. وكان الشهداء الذين يجدمهم يدعون له قائلين: ( لابد لك من سفك دمك على اسم السيد المسيح لشحسب ق عداد الشهداء ). ولما أراد السيد (\"' أى من أقفهص وهي قرية مازالت بنفس اسمها تابعة لمركز الفشن محافظة بئ سويف.\nالمسيح أن يتمم ما أنبأه به القديسون ويريحه من أتعاب هذا العالم؛ ظهر له في رؤيا الليل وأمره أن يذهب إلى أركاديوس وال سمنود ويعترف أمامه بالسيد لمسيح؛ » فانطلق إلى هناك كأمر الرب» فعذبه الوالي عذابات شديدة بأنواع مختلفة وكان الرب يقويه. . وصلى صلاة الأرض فاها وابتلعت سبعين وثنا وأربعين كاهنا كانوا فلما رأى الوالي هلاك الكهنة وزوال الآلهة آمن بالسيد المسيح؛ ثم مضى مع القديس إلى والى أتريب الذي عذبهما كثرا » ولما صلى القديس أرسل الرب ملاكه إل برا الأصنام فتزع رؤوس الأصنام وسودها بالرماد» فآمن والى أتريب على يدي القديس يوليوس. ثم ذهب ثلاثتهم إلى الكسندروس والي طوة ”\"؛ فكتب قضيتهم وأمر الجند فقطعوا رؤوسهم. وكان معهم ابنا.\nيوليوس تادرس ويونياس وعبيده وجماعة عظيمة كان عددها نحو ألف وخمسمائة شخص» استشهدوا جميعهم ونالوا إكليل الشهادة.\nنقل المؤمنون جسد يوليوس الأقفهصي مع جسد ابنيه إلى الإسكندرية. ولما انتهي الاضطهاد وتولى الملك قسطنطين زمام ممع بسيرة الشهيد العظيم يولموس الأقفهصي؛ فأعجب به وأرسل أموالا إلل مصر وأمر بأن ب تبنى باسمه كنيسة في مدينة الإسكندرية فينيت وثقل جسده إليها وكزسها البابا الكسندروس البطريرك التاسع عشر في 8 ؟ بابه.\nبركة صلوات هؤلاء الشهداء القديسين فلتكن معنا ولربنا المجد دائما أبديا آمين.\n)0 طوة: كانت بقاياها بقرب طنطا محافظة الغربية وحلت ملها محلة مرحوم."},{"d":23,"t":["استشهاد القديسين أونانيوس وأندراوس أخيه","تذكار القديسة الشهيدة تكلا"],"b":"مهن - في مثل هذا اليوم من سنة 74 للشهداء ( )؛ استشهد القديسان الباران أونانيوس وأندراوس أخاه.\nكان هذان القديسان ابنين لأحد أكابر لدة بفلسطين. فاتفقا منذ صباهما على عيشة الرهبئة. فانطلقا إلى أحد أديرة الشام هناك. وبعد قليل » قصدا القديس مكازيوس الكبير ببرية شيهيت وتتلمذا له مدة ثلاثين عاماء أمضياها في الأصوام والصلوات والاتضاع والمحبة. . فشاع خبر نسكهما وعلمهما. فتم اختيار أونانيوس أستفا .6 وأندراوس قسا. فرعيا رعيه المسيح أحسن رعاية. ولما ممع بهما الإمبراطور يوليانوس الجاحد وحاول أن يردهما عن الإيمان بالسيد المسيح؛ فعذيهما بعذابات كثيرة حتى أسلما نفسيهما الطاهرتين بيد السيد المسيح. ونال كل منهما ثلاثة أكاليل واحد من أجل الرهبنة» والثاني من أجل الكهنوت والخدمة» والثالث من أجل الشهادة للمسيح.\nبركة صلاتهما فلتكن معنا أمين.\nوفيه أيضا تعيد الكنيسة بتذكار القديسة تكلا أول الشهيدات, تلميذة بولس الرسول» مشال البتولية والطهارة؛ الجهاد واحتمال الشدائد.\nولدت تكلا في مدينة أيقونية , إحدى مدن آسيا الصغرى» من أبوين شريفين وثنيين» كانت بارعة الجمال؛ لأحد أشراف تلك المدينة. وعندما وصل القديس بولس الرسول إلى أيقونية '\"؛ في رحلته التبشيرية تكلا. أعجبت بتعاليمه.\nثم آمنت بالسيد المسيح واعتمدت» ونذرت بنوليتها للرب» وهجرت خطيبها. وتبدلت حياة القديسة بعد الإيمان؛ فبعد أن كانت تهتم بزينة الجسد» بدأت تهتم بزينة الروح.\nأمها هذا التغيير في سلوكهاء ولما سألتها عن سر ذلك. قالت لا أنها أصبحت مسيحية وأنها نذرت بتوليتها للرب يسوع. غضبت أمها وحاولت إقناعها فرفضت. وهنا لجأت الأم إلى حاكم المدينة واستعانت به. فاستحضر تكلاء وحاول إقناعها بترك المسيحية والعودة إل الآلهة» وإل خطيبها. فرفضت بشدة ولم تخف من تهديداته. فأمر بإضرام نار حامية وطرحها فيها. فأرسل الرب مطرا غزيرا أطفا النار» وخرجت تكلا أيقونية : مدينة يجنوب آسيا الصغرى ( تركيا ) واسمها الحالي قونيا.\n)0 أع :له بعد ذلك تركت مدينتها وذهمت تسعى وراء القديس بولس.\nفأخذها معه إلى مدينة أنطاكية وهناك تركها لتخدم بين النساء.\nقبض عليها هناك الوالي وطرحها للوحوش. لكن الوحوش 1 .\nثم ألقاها في جب مليء بالأفاعي السامة» فلم تؤذها.\nفأمر بإطلاق سراحها.\nالقديس بولس وعزاها. ثم رجعت إل أيقونية مسقط رأسها لتبشر أهل مدينتها بالإيمان الحي. ولما وجدت أن أمها مازالت تضغط عليها وتحاول إرجاعها إلى الوثنية» تركت أيقونية وعادت إل صور بالشام؛ لمتابعة خدمتها. فآمن على يديها شعب غفير. 0 ض م في أواخر حياتها عكفت على الخلوة والتأمل والنسك»؛ وقد وهبها الله موهبة شفاء الأمراض. فنال.كثيرون الشفاء بصلواتها.\nأخيرا رقدت في الرب وهي في سن التسعين ودفنت في سلوكية ميناء أنطاكية. وتدعوها الكئيسة ) الشهيدة بدون سفك دم .\nبركة صلواتها فلتكن معنا؛ ولربنا المجد دائما أبديا آمين."},{"d":24,"t":["استشهاد القديس كودارتوس أحد السبعين رسولا وتلميذا","نياحة القديس غريغوريوس الثيئولوغوس","نياحة القديس غريغوريوس الراهب"],"b":"- في مثل هذا اليوم استشهد القديس كودارتس أحد السبعين رسولا.\nولد هذا القديس بمدينة أثينا. وكان من أعظم علمائها وفلاسفتها فآمن بالسيد المسيح. فعينه الرب من ضمن السبعين رسولا. ولما نال نعمة الروح القدس المعزى في يوم الخمسين» انطلق وبس بالإنجيل في بلاد كثيرة. فأنار أهلها بالإيمان ثم عمدهم.\nأخيرا عاد إل مسقط رأسه أثيناء وطفق يعلم فيها. فقبضوا عليه وعذبوه بأنواع كثيرة. ثم طرحوه في النار. فنال إكليل بركة صلواته فلتكن أمين.\n\"- وفيه أيضا من مسنة للشهداء تنيح القديس\" غريغوريوس النزينزى الناطق بالإلهيات. وهو ابن غريغوريوس أسقف نزينز. ض ولد هذا القديس سنة في بلدة إريانزو من أعمال ولما بلغ سن الشباب أرسله والده إل مدارس قيصرية الكبادوك ثم إلى الإسكندرية. ثم إلى أثينا. فتعلم المنطق والشعر والفلسفة والعلوم اللاهوتية. وقد أمضى في ذلك واي عشرة سنة. صادق خلالها القديس باسيليوس الكبير.\nواتفق كلاهما على حياة التكريس.\nرجع غريغوريوس إلى وطنه وظل يساعد أباه فى أعمال لأنه كان قد بلغ سن الشيخوخة. فرسمه أبوه قسا سنة 7 م. ولما ارتقى القديس باسيليوس إلى رئاسة الكهدوت في الكبادوك ؛ رسم صدذيقه غريغوريوس أسقفا على سنة لكنه لم يدخل الإيبارشية؛ لأنها كانت موضع بين القديس باسيليوس والأسقف ألتيموس» ومنعه جنود الإمبراطور فالنس الأريوسى من دخولا.\nعاد إلى نزيدز ليساعد أباه في أعمال الأسقفية. وبعد نباحة والده سنة ؛ لالم مضى إلى دير منفردا به للعبادة والتأمل مدة خمس سنوات. ثم ذهب إلى القسطنطينية سنة 9 الام بحت إلحاح شعبها الأرثوذكسي الذي أتعبه الأريوسيون بتعاليمهم الفاسدة.\nوهناك رد كثيرين من الأريوسيين إلى الإيمان المستقيم. وكانت المسكوني الثاني عام بحث المجتمعون هذا الأمر أخرى. فترك القسطنطينة بعد أن ودع الأساقفة والشعب بخطاب مؤثر للغاية. وذهب إلى نزينزء ليقاوم بدعة وبعدها انفرد في أريائز مع بعض النساك» حيث ألف رسائل عديدة ضد الأريوسية وغيرها من الحرطقات. أخرا ديف رقد في الرب» وتلقبه الكنيسة بالثيئولوغوس ( أي الناطق ) بسبب عظاته اللاهوتية العميقة؛ كما إنه ينسب إليه القداس الغريغوري. ض بركة صلواته فلتكن معنا أمين.\nوفيه أيضا تنيح القديس غريغوريوس الراهب. هذا كان من بلاد الصعيد. ولد من أبوين مسيحيين من ذوى الثروة فأدباه بكل وعلماه علوم الفصاحة والطب. ثم ثقفاه في علوم الكنيسة. بعد ذلك قدماه للأب الأسقف الأنبا إسحاق أسقف الإيبارشية فرسمه شماسا. ومنذ حدائته كان يميل إلى الوحدة.\nلذلك كان يداوم على زيارة القديس باخوميوس أب الشركة.\nوبعد قليل ترهب عند القديس باخوميوس. وسار في طريق الفضيلة شوط بعيدا لمدة ثلاث عشرة سنة.\nبعد ذلك جاء القديس مكاريوس الإسكندري لزيارة الآديرة . وعند رجوعه طلب منه الراهب غريغوريوس أن يمضى معه إلى جبل القلالي. فمكث هناك ستتين. وبيحد ذلك استأذن من القديس مكاريوس وحفر لنفسه مغارة في الجبل مكث فيها سبع سنين. وكان يزور القديس مكاريوس مرتين في السنة في عيدي الميلاد والقيامة.\nولا أكمل جهاده الحسن» أعلمه ملاك الرب بانتقاله بعد ثلاثة أيام. فدعا شيوخ البرية وودعهم وتنيح بسلام.\nبركة صلواته فلتكن معنا ولربنا المجد دائما أبديا آمين."},{"d":25,"t":["تذكار نياحة يونان النبي","استشهاد القديس موريس قائد الفرقة الطيبية"],"b":"مثل هذا اليوم تنيح الي يونان بن أمتاى من سبط زبولون وهو من جحت حافر بالقرب من الناصرة بالجليل» وكان في أيام الثاني ملك إسرائيل الذي ملك بين -7//7 2 كا ق. م ويقول عنه تقليد اليهود أنه ابن أرملة صرفة صيدذا الذي أقامه إيليا النى من الموت \". ض وكلمة يوثان من أ لأصل العبري يونا ومعناها ) حمامة 4 وقد أمره الله أن بمضى إلى مدينة نيدوى \" بالعراق» وينادى أهلها ليتوبوا إلى الله إذ صعد شرهم إلى السماء» ولكنه خالف أمر الله\" فقام وهرب إل ترشيش ؟ في سفينة» فهاج البحر حتى كادت السفينة تغرق» فخاف كل من بالسفينة وطرحوا الأمتعة في البحر كل واحد إل إلهه» أما يونان فكان قد نزل إلى جوف السفينة ونام يوما عميقا. فجاء إليه رئيس النواتية وأيقظه قائلا:\n\" لماذا تنام » قم اصرخ إلى إلهك للا نهلك.” ثم ألقوا قرعة ليعرفوا بسبب من هذه البلبة فوقعت على يونان» ولما سألوه قال: «أنا 0 تقوم الآن مدينة الموصل بالعراق مكان مدينة نينوى القدعة.\n1 مم 0 0 مم هه اجو ع 0 م م 0 ترضيش هي ترئيسوس وتقع جنوب أسبانيا قرب جبل طارق.\nمن وجه الله ) فقالوا له ماذا نصنع بك ليهدا البحرء فقال ألقوني في البحر فيهدا لأني عالم أنه بسبب قد حدث هذا النوء يونان وطرحوه في البحر قتوقف عن هيجانه. أما الرب فعا حوتا عظيما لييتلع يونان» فكان في جوف الحوت ثلا يام وثلاث ليال.\nوصلى يونان في بطن الحوت صلاة عميقة '\". فأمر الرب الحوت فقذفه إلى البر. ثم صار قول الرب إلى يونان ثانية قم اذهب إلى نينوى وناد لها بالمناداة الت أنا مكلمك مها. . فقام يونان وذهب إلى نينوى ونادى فيها قائلا بعد أربعين يوما تتقلب فآمن أهل نينوى بالله وتابوا توبة حقيقية بالصوم والصلاة والتذلل. فلما رأى الله توبتهم الحقيقية رحمهم وغفر ورفع غضبه عنهم.\nبعد ذلك رجع يونان إلى أرض إسرائيل» واعتزل في مكان قريب من مديئة صور بالشام » إلى أن مات وعمره حوالي مائة سنة. وتنأ ف أياء أموص وعزيا ملوك يهوذا.\nبركة صلواته فلتكن معنا آمين.\n\" - وفيه أيضا من سنة 9 للشهداء ( ).؛ استشهد القديس موريس قاد الفرقة الطييبية الت انتقلت من طيبة إلى مدينة أجونام 0 لإخماد ثورات قبائل الباجورء وكان عددها. 111 )0 أجونام: مدينة بسويسرا حاليا هي مدينة سان موريس بمقاطعة الفاليس كان الإمبراطور مكسيميانوس يقيم حينئذ بمدينة '؟» فأمر القائد موريس وأعضاء الفرقة بتقديم الذبائح للآلمة قبل المجوم » فرفضوا إطاعة الأمرء فأمر الإمبراطور بقتل غشر الفرقة لإرغام بقيتها على طاعته؛ عند ذلك تزايد حماس بقية الفرقة للتمسك بالإيمان المسيحي؛ | فغضب الإبراطور وأمر بقتل عشر المتبقيين. وكان القديس موريس يشجع الجنود على التمسك بإيمانهم مع إعلان ولائهم ازداد الإمبراطور هياجا وأمر بإبادة الكتيبة الموجودة بأجونام والقيام بتعقب بقية كتائب الفرقة الطيبية ف بسويسرا وإيطاليا وألمانيا.\nأما القديس موريس فال كليل الشهادة ومعه الكتيية \"الي ل أجونام والبالغ عددهم جنديا. وكان الرب يجري العديد من المعجزات حتى أمن عدد كبير من سكان المناطق.\nويعتبر القديس موريس هو شفيع بلاد سويسراء وبنيت على.\nكثير من الكنائس والمؤسسات الاجتماعية» والأديرة.\nوف يوم 8 توت سنة 767 للشهداء (/7 سبتمبر ) استلم قداسة البابا شنوده الثالث البطريرك المائة والسابع عشر جزءا من رفات القديس موريس» يوجد حاليا بمنطقة الأنبا رويس بالعباسية بالقاهرة.\nبركة صلواته فلتكى. معنا. ولربنا المجد دائما أبديا أمين.\nمديئة بسويسرا حاليا هي مديلئة مارتيئن."},{"d":26,"t":["بشارة زكريا الكاهن بميلاد يوحنا المعمدان"],"b":"ربت الكنيسة المقدسة أن تحتفل في مثل هذا اليوم بتذكار بشارة رئيس الملائكة جبرائيل» للقديس زكريا بميلاد يوحنا السابق.\n. وذلك أن الله أرسل رئيس الملائكة جبرائيل إلى زكريا الكاهن بينما كان يرفع البخور داخل الهيكل. وكان جمهور الشعب خارجا وقت فلما رأى زكريا الملاك اضطرب وخاف. فقال له الملاك لا تخف يا زكريا لأن طلبتك قد سمعت وامرأتك أليصابات ستلد لك ابنا يوحنا. ويكون لك فرح وابتهاج» وكثيرون سيف رحون لأنه يكون عظيما أمام الرب ومن بطن أمه بمتلىء من الروح القدس ويرد كثيرين من بنى إسرائيل إلى الرب إلههم» ويتقدم أمامه إيليا وقوته » ليبرد قلوب الآباء إلى الأبناء والعصاة إل فكر الأبرار ويهىء للرب شعبا مستعدا. فقال زكريا للملاك كيف أعلم هذا لأني أنا شيخ وامرأتي متقدمة في أيامها. فأجاب الملاك وقال له ( أنا جبرائيل الواقيف أمام الله؛ وأرسلن الله لأبشرك بهذاء وها أنت تكون إلى اليوم الذي يكون فيه هذاء لأنك لم تصدق كلامي الذي في حينه \" ) ثم مضى الملاك وخرج زكريا وهو لا يستطيع أن امرأته أليصابات. وتمت بشارة الملاك.\n' ولربنا المجد دائما أبديا آمين.\n)لو نم-"},{"d":27,"t":["استشهاد القديس أسطاثيوس وولديه وزوجته"],"b":"في مثل هذا اليوم استشهد القديس أسطائيوس وولداه وزوجته.\nوكان يدعى أولا بلاسيداس» وكان وثيا » وأحد وزراء مملكة الرومان في عهد الإمبراطور تراجان (9/8 ). وكان شديد على الفقراء؛ ولم يسمح الله أن يضيع تعبه» فبينما كان يصيد إحدى المرات كعادته» رأى صليا مرتفعا ؛ ومع صوت الرب يسوع يدعوه لليمان. ولما رجع إلى بيته روى لزوجته وولديه ما حدث» ثم توجهوا إلى أسقف روما الذي علمهم الإيمان وعمدهم, وغير اسمه إلى أسطاثيوس. ض ثم ما لبث أن حلت به نكبات متوالية مثل أيوب الصديق» ففقد وكل أمواله وخرج من روما بسبب الفقر» وفي الطريق فقد زوجته وولديه,؛ وبتدبير الله شمحب البشرء اجتمعوا معا مرة أخرى» ففرحوا بذلك فرحا عظيما. ض ولما تولى أدريانوس الملك سنة م سمع عن أسطاثيوس وعائلته نهم صاروا مسيحيين فاستدعاهم وأمرهم بالتبخير للأوثان فرفضوا.\nعليهم الوحوش المفترسة الجائعة فلم تؤذهم. . وأخيرا وضعهم ق زيت مغلي فأسلموا أرواحهم بيد الرب ونالوا إكليل الشهادة.\nبركة صلواتهم فلتكن معناء ولربنا المجد دائما أبديا آمين.\nللف"},{"d":28,"t":["استشهاد القديسين أبادير وإيرائى (\" أخته"],"b":"في مثل هذا اليوم استشهد القديسان أبادير وإيرائى أخته ابنا أخت واسيليدس الوزير وقد ولدا وترييبا في أنطاكية وكان أبادير قائدا عظيما ف جيش دقلديانوس. فلما كفر دقلديانوس واضطهد ظهر السيد المسيح لأبادير في رؤيا الليل» وطلب منه أن يذهب مع أخته إيرائى إلى مصر لينالا إكليل الشهادة. وقد رأت أخته أيضا نفس الرؤيا. فانطلقا بفرح ليتمما ما أمرهما به الرب» ووصلا إلى الإسكندرية ومنها إلى أنصنا حيث اعترفا أمام إريانوس بالسيد المسيح» فعذبهما عذابات شديدة. وكان الرب يقويهما في وسط هذه الآلام الشديدة وقد حمل نفسيهما ليشاهدا الفردوس» فامتلا كل منهما قوة وثبات. ثم كتب الوالي قضيتهما وحكم بقطع رأسيهما فتلا إكليل الشهادة. . وقام بعض المؤمنين بتكفين جسديهما وأخذهما خماس يدعى صموئيل إلى منزله حت انقضاء زمن الاستشهاد حيث بيت هما كنيسة عظيمة ويوجد الآن باسميهما كنيسة في أسيوط وأخرى في مركز ديروط محافظة أسيوط.\nبركة صلواتهما فلتكن معناء ولربنا المجد دائما أبديا آمين.\n) 0 بعص المصادر تذكر اسم يري بدلا من إيرائى."},{"d":29,"t":["تذكار الأعياد الثلاثة السيدية الكبرى","استشهاد القديسة أربسيما ومن متها","استشهاد القديسة فبرونيا"],"b":"- ربت الكنيسة أن تعيد في اليوم التاسع والعشرين من كل شهر قبطي بتذكار الأعياد السيدية الكبرى: البشارة والميلاد والقيامة؛ حيث يصلى فيها بالطقس الفرابجي مع بقاء القراءات كما هي ولا يتم هذا الاحتفال ج شهري طوبه وأمشير اللذين يرمزان إلى الداموس والأنبياء. ولأنهما يسبقان شهر برمهات الذي ثمت فيه البشارة بميلاد الرب يسوع.\nبركة هذه الأعياد فلتكن معنا آمين.\n7 - وفيه أيضا استشهدت القديسات العذارى أربسيما وأغاثي أمها عذراء في أياء الملك دقلديانوس.\nهذا الطاغية أن يتزوج أجل فتاة. فأرسل بعض معاونيه إلى جميع البلاد ليبحثوا له عن أجمل فتاة يقع نظرهم عليها. فلما وصلوا إلى نواحي روما دخلوا بيتا للعذارى فوجدوا هذه القديسة أربسيما ؛ ولم يكن من يماثلها في الجمال. فرجعوا إل الملك يصفونا له؛ ففرح جدا وأرسل يدعو الملوك والرؤساء فلما علمت أربسيما والعذارى بذلك.\nمن البيت وهن يتوسلن إلى السيد المسيح أن يعينهن ويحفظ بتوليتهن. فذهين إلى بلاد أرمينيا في ولاية ترايداتة الملك.\nداخل معصزة في أحد البساتين الخربة. وكانت واحدة الزجاج وتبيعه وتحصل بثمنه على قوت لهن جيعا.\nطلب دقلديانوس أربسيما فلم يجدها. فبحث عنها كثيرا حتى عرف أنها في بلاد أرمينيا فأرسل إلى تريداتة لكى يبحث عنها إليه. فلما وجدها تريداتة ورأى جالها أراد أن يأخذا فلم تمكنه من ذلك. فأحضر لها أمها لكي تقنعها لكنها كانت تعضدها وتوصيها بأن لا تترك عريسها الحقيقى الرب يسوع المسيح. فلما علم ترايداتة بما فعلته أمها أمر بكسر أستانها أما أربسيما فأمر بتعذييها ثم بقطع رأسها. فربطها الجند وقطعوا لسانا وقلعوا عينيهاء ثم قطعوها إربا إربا. ثم أمر تريداتة بقخل بقية العذارى» فقتلهن الجند بعد أن عذبوهن بعذابات أليمة فنلن أكاليل الشهادة. 0 بركة صلواتهن فلتكن معنا آمين.\n> وفيه أيضا من سنة 43 للشهد أء ( ل م ف عهد | لبابا خائيل الأول » السادس والأربعين من بطاركة الكرسي المرقسي» وفي ولاية عبد الملك بن مروان الذي كان يضطهد المسيحيين» هاحمه أبو العباس»؛ فهرب مجنوده إلى الوجه القبلي» وأمرهم هدم الكنائس والأديرة والقخل والسلب والنهب. وكان هناك قرب أخميم دير للراهبات به ثلاثون راهبة. فدخل إليه الجنود وبعدما وجدوا بين الراهبات راهبة بارعة الجمال تدعى فبرونيا رتلف فأرادوا أن يأخذوها ليقدموها هدية للسلطان: فلما سمحت إلى قائدهم وطلبت مهلة» ودخلت إلى قلايتها وصلت إلى الله باكية طالبة الخلاص. وسرعان ما خرجت إليهم إليهم أن يتركوها لعبادتهاء مقابل جميل تسديه إليهم » تعلمته من أسلافها. وكان هذا الجميل» زيتا تقتنيه؛ إن دهن به أي جزء من الجسم لا تعمل فيه السيوف. ولكي دهنت عنقها بالزيت وطلبت من القائد أن يجعل أشجع جنوده يضربها بكل قوته بسيفه الحاد. وما أن فعل ذلك حتى رأس العذراء العفيفة عن جسدها ونالت إكليل الشهادة.\nأما الجند فاعتراهم خوف شديد» وأسرعوا بمغادرة الديرء بعد أن تركوا كل ما كانوا قد نهبوه. فأخذت أخواتها الراهمات جسدها الطاهر وكفنوه ودفنوه بإكرام جزيل.\nبركة صلواتها فلتكن معناء ولربنا المجد دائما أبديا آمين."},{"d":30,"t":["تذكار المعجزة التي صنعها الرب مع القديس أثناسيوس الرسولي"],"b":"تحتفل الكنيسة في هذا اليوم بتذكار المعجزة العظيمة التي صنعها الرب مع القديس العظيم أثناسيوس الرسولي البطريرك العشرين للكرازة المرقسية. وذلك أن الملك قسطنطينوس ابن الملك قسطنطين لما اعتدق تعاليم أريوس الحهرطوقي» أرسل إلى الإسكندرية شخصا يدعى جورجيوس ومعه خمسمائة جندي ورسائل بتعيينه بطريركا على الإسكندرية بدلا من القديس أثناسيوس الرسولي. ولما وصل هذا الرجل إلى المدينة تل كثيرين من أهل الإسكندرية. أما القديس أثناسيوس فبقى منتفيا ثلاث سنين. ثم خرج إلى القسطنطينية وطلب من الملك قسطنطينوس إما أن يرده إلى كرسيه أو يقتله لينال اكليل الشهادة وكان ذلك سنة 211 م.\nأما الملك فأمر أن يوضع القديس في مركب صغير ويترك في البحر بغير خبز ولا ماء ولا مدبر للمركب ظنا منه أنه بذلك يهلك إما أو بالجوع والعطش. ولكن بتدبير من الله وعنايته» سارت المركب في هدوء وسلام كأنها محمولة على أجنحة الملائكة. إلى أن وصلت مدينة الإسكندرية في ثالث يوم. ولما علم المؤمنون بقدومه جدا وخرجوا إليه واستقبلوه بالألحان والتسابيح حتى أدخلوه إلى الكنئيسة وأخرجوا منها جورجيوس وأصحابه. فجعل القديس هذا اليوم عيدا عظيما للرب الذي له المجد دائما أبديا آمين.\nيتف"}];
